	void verify_live_close_cut_terminalizes_every_preexisting_map_outcome()
	{
		const auto drain_composite = [](reader_candidate_setup& setup,
										sqlite_shm_reader_live_close_obligation& close,
										const sqlite_shm_callback_execution_receipt& unmap_callback,
										const sqlite_shm_callback_execution_receipt& close_callback,
										const std::uint8_t marker)
		{
			const auto terminal = sqlite_same_process_shm_lease_test_peer::reader_session_terminal(
				setup.session_request,
				sqlite_shm_reader_session_terminal_kind::failure,
				identity("test.registry.reader-live-close-map-session", marker));
			require(
				setup.fixture.registry
					->complete_reader_session(*setup.fixture.family_pin, setup.session, terminal)
					.has_value(),
				"drain the post-cut map session");
			auto ready = setup.fixture.registry->poll_reader_live_close_unmap_cut(
				*setup.fixture.family_pin, setup.open, close, close_callback);
			require(ready &&
						ready->progress ==
							sqlite_shm_reader_unmap_cut_progress::native_effect_ready &&
						close.native_effect_ready(),
					"post-cut map terminal leaves the same composite ready after session drain");
			const auto unmap_receipt =
				sqlite_same_process_shm_lease_test_peer::reader_unmap_terminal(
					close,
					unmap_callback,
					sqlite_shm_reader_unmap_evidence_kind::exact_native_result,
					sqlite_ok_status,
					0,
					0,
					identity("test.registry.reader-live-close-map-unmap-effect", marker),
					identity("test.registry.reader-live-close-map-unmap-latch", marker));
			auto unmapped = setup.fixture.registry->complete_reader_live_close_unmap(
				*setup.fixture.family_pin, setup.open, close, unmap_receipt);
			require(unmapped &&
						unmapped->kind() ==
							sqlite_shm_reader_unmap_terminal_kind::retired_confirmed &&
						close.close_ready(),
					"post-cut map terminal preserves exactly one confirmed composite unmap");
			const auto close_receipt =
				sqlite_same_process_shm_lease_test_peer::reader_close_terminal(
					close,
					close_callback,
					sqlite_shm_reader_close_evidence_kind::exact_native_result,
					sqlite_ok_status,
					identity("test.registry.reader-live-close-map-close-effect", marker));
			auto closed = setup.fixture.registry->complete_reader_live_close(
				*setup.fixture.family_pin, setup.open, close, close_receipt);
			require(closed.has_value(),
					"post-cut map terminal admits its confirmed close terminal");
			require(closed->kind() == sqlite_shm_reader_close_terminal_kind::closed,
					"post-cut map terminal records one confirmed close");
			require(setup.fixture.registry->release_reader_open(setup.open).has_value(),
					"release the post-cut map terminal reader open");
			retire_writer(*setup.coordinator, setup.holder, static_cast<std::uint8_t>(marker + 1U));
			require(setup.coordinator->revoke_writer_eligibility(setup.eligibility).has_value(),
					"revoke post-cut map fixture writer eligibility");
			clean_fixture(setup.fixture);
		};

		for (const auto [marker, exact_ok] :
			 std::array{std::pair{140U, true}, std::pair{150U, false}})
		{
			auto setup = make_reader_candidate_setup(static_cast<std::uint8_t>(marker));
			auto handoff = form_reader_group(setup, static_cast<std::uint8_t>(marker + 1U));
			const auto map_request = reader_attachment_map_request(
				setup.session_request, static_cast<std::uint8_t>(marker + 2U));
			auto map = setup.fixture.registry->begin_reader_map(
				*setup.fixture.family_pin, setup.session, map_request);
			require(map && map->valid(), "begin map before live-close publication cut");
			const auto unmap_callback = callback(static_cast<std::uint8_t>(marker + 3U));
			const auto close_callback = callback(static_cast<std::uint8_t>(marker + 4U));
			auto close = setup.fixture.registry->begin_reader_live_close(
				*setup.fixture.family_pin,
				setup.open,
				handoff,
				sqlite_shm_reader_unmap_request{unmap_callback, 0, 0},
				sqlite_shm_reader_close_request{close_callback});
			require(close && close->valid() && !close->native_effect_ready() && !handoff.valid(),
					"live-close cut freezes the earlier map before its terminal");

			if (exact_ok)
			{
				const auto receipt = sqlite_same_process_shm_lease_test_peer::reader_attachment_map(
					map_request,
					setup.holder.generation(),
					mapping(setup.writer_attempt.native_page.get()),
					identity("test.registry.reader-live-close-exact-map-effect",
							 static_cast<std::uint8_t>(marker)));
				auto suppressed = setup.fixture.registry->commit_reader_map(
					*setup.fixture.family_pin, *map, receipt, setup.session);
				require(!suppressed &&
							suppressed.error().reason ==
								sqlite_shm_lease_rejection_reason::retiring &&
							suppressed.error().action ==
								sqlite_shm_lease_recovery_action::outer_ioerr_no_retry &&
							!map->valid() && setup.session.valid() && close->valid() &&
							!close->native_effect_ready() &&
							setup.coordinator->snapshot()
									.reader_existing_group_deferred_cleanup_count == 1U,
						"exact post-cut map effect is recorded but never publishes its pointer");
			}
			else
			{
				const auto receipt = sqlite_same_process_shm_lease_test_peer::
					reader_existing_group_predecessor_mismatch(
						*map,
						map_request,
						sqlite_readonly_status,
						setup.writer_attempt.native_page.get(),
						identity("test.registry.reader-live-close-mismatch-effect",
								 static_cast<std::uint8_t>(marker)));
				auto suppressed =
					setup.fixture.registry->complete_reader_existing_group_predecessor_mismatch(
						*setup.fixture.family_pin, *map, receipt, setup.session);
				require(suppressed && suppressed->outward_status() == sqlite_ioerr_status &&
							suppressed->native_mapping() == nullptr && !map->valid() &&
							setup.session.valid() && close->valid() &&
							!close->native_effect_ready() &&
							setup.coordinator->snapshot()
									.reader_existing_group_deferred_cleanup_count == 1U,
						"mapped post-cut result reuses the existing composite cleanup owner");
			}
			drain_composite(setup,
							*close,
							unmap_callback,
							close_callback,
							static_cast<std::uint8_t>(marker + 5U));
		}

		constexpr std::uint8_t marker = 160U;
		auto setup = make_reader_candidate_setup(marker);
		auto handoff = form_reader_group(setup, marker + 1U);
		const auto map_request = reader_attachment_map_request(setup.session_request, marker + 2U);
		auto map = setup.fixture.registry->begin_reader_map(
			*setup.fixture.family_pin, setup.session, map_request);
		const auto unmap_callback = callback(marker + 3U);
		const auto close_callback = callback(marker + 4U);
		auto close = setup.fixture.registry->begin_reader_live_close(
			*setup.fixture.family_pin,
			setup.open,
			handoff,
			sqlite_shm_reader_unmap_request{unmap_callback, 0, 0},
			sqlite_shm_reader_close_request{close_callback});
		require(map && close && close->valid(),
				"begin opaque map and seal its exact live-close composite");
		auto opaque = setup.fixture.registry->complete_reader_opaque_attachment_uncertainty(
			*setup.fixture.family_pin, *map, setup.session);
		const auto lifecycle =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
		require(
			opaque && opaque->outward_status() == sqlite_ioerr_status &&
				opaque->native_mapping() == nullptr && !map->valid() && !setup.session.valid() &&
				!close->valid() && setup.coordinator->snapshot().quarantined &&
				setup.fixture.registry->snapshot().quarantined_family_count == 1U &&
				lifecycle.attachment_groups.size() == 1U && lifecycle.open_epochs.size() == 1U &&
				lifecycle.attachment_groups.front().phase ==
					detail::sqlite_shm_reader_attachment_group_phase::terminal_quarantined &&
				lifecycle.open_epochs.front().phase ==
					detail::sqlite_shm_reader_connection_close_phase::terminal_quarantined,
			"opaque post-cut map quarantines the composite group, open, and family at once");
	}

	void verify_two_pre_cut_maps_converge_on_one_live_close_composite()
	{
		enum class terminal_kind : std::uint8_t
		{
			exact,
			mismatch,
		};
		struct row
		{
			std::uint8_t marker;
			terminal_kind first;
			terminal_kind second;
		};

		for (const auto current :
			 std::array{row{21U, terminal_kind::exact, terminal_kind::exact},
						row{41U, terminal_kind::mismatch, terminal_kind::mismatch},
						row{61U, terminal_kind::exact, terminal_kind::mismatch},
						row{71U, terminal_kind::mismatch, terminal_kind::exact}})
		{
			auto setup = make_reader_candidate_setup(current.marker);
			auto handoff = form_reader_group(setup, current.marker + 1U);
			auto second_pre_sqlite = setup.pre_sqlite;
			second_pre_sqlite.read_transaction_epoch =
				identity("test.registry.reader-live-close-pair-transaction", current.marker);
			second_pre_sqlite.decode_attempt =
				identity("test.registry.reader-live-close-pair-decode", current.marker);
			second_pre_sqlite.authority_read_receipt =
				identity("test.registry.reader-live-close-pair-authority", current.marker);
			auto second_admission = setup.fixture.registry->admit_reader_session_before_sqlite(
				*setup.fixture.family_pin, setup.open, second_pre_sqlite);
			require(second_admission &&
						second_admission->kind() ==
							sqlite_shm_reader_session_admission_kind::active_group_owner_admitted &&
						second_admission->proposal_request(),
					"admit the second pre-cut live-close group session");
			const auto second_session_request = *second_admission->proposal_request();
			auto second_session = second_admission->take_session();
			require(second_session && second_session->valid(),
					"take the second pre-cut live-close group session");

			const auto first_map_request =
				reader_attachment_map_request(setup.session_request, current.marker + 2U);
			const auto second_map_request =
				reader_attachment_map_request(second_session_request, current.marker + 3U);
			auto first_map = setup.fixture.registry->begin_reader_map(
				*setup.fixture.family_pin, setup.session, first_map_request);
			auto second_map = setup.fixture.registry->begin_reader_map(
				*setup.fixture.family_pin, *second_session, second_map_request);
			require(first_map && first_map->valid() && second_map && second_map->valid(),
					"begin two maps before the shared live-close cut");

			const auto unmap_callback = callback(current.marker + 4U);
			const auto close_callback = callback(current.marker + 5U);
			auto close = setup.fixture.registry->begin_reader_live_close(
				*setup.fixture.family_pin,
				setup.open,
				handoff,
				sqlite_shm_reader_unmap_request{unmap_callback, 0, 0},
				sqlite_shm_reader_close_request{close_callback});
			require(close && close->valid() && !close->native_effect_ready() && !handoff.valid(),
					"one live-close composite seals both pre-cut maps and sessions");

			const auto complete_map = [&](sqlite_shm_reader_attachment_map_inflight& map,
										  sqlite_shm_reader_session& session,
										  const sqlite_shm_reader_attachment_map_request& request,
										  const terminal_kind kind,
										  const std::uint8_t marker)
			{
				if (kind == terminal_kind::exact)
				{
					const auto receipt =
						sqlite_same_process_shm_lease_test_peer::reader_attachment_map(
							request,
							setup.holder.generation(),
							mapping(setup.writer_attempt.native_page.get()),
							identity("test.registry.reader-live-close-pair-exact-effect", marker));
					auto completed = setup.fixture.registry->commit_reader_map(
						*setup.fixture.family_pin, map, receipt, session);
					require(!completed &&
								completed.error().reason ==
									sqlite_shm_lease_rejection_reason::retiring &&
								completed.error().action ==
									sqlite_shm_lease_recovery_action::outer_ioerr_no_retry,
							"exact mapped result after the cut is suppressed without a new owner");
				}
				else
				{
					const auto receipt = sqlite_same_process_shm_lease_test_peer::
						reader_existing_group_predecessor_mismatch(
							map,
							request,
							sqlite_readonly_status,
							setup.writer_attempt.native_page.get(),
							identity("test.registry.reader-live-close-pair-mismatch-effect",
									 marker));
					auto completed =
						setup.fixture.registry->complete_reader_existing_group_predecessor_mismatch(
							*setup.fixture.family_pin, map, receipt, session);
					require(completed && completed->outward_status() == sqlite_ioerr_status &&
								completed->native_mapping() == nullptr,
							"mismatched mapped result after the cut reuses the composite owner");
				}
				require(!map.valid() && session.valid() && close->valid() &&
							!close->native_effect_ready() &&
							setup.coordinator->snapshot()
									.reader_existing_group_deferred_cleanup_count == 1U,
						"each post-cut map terminal converges on the same deferred composite");
			};

			complete_map(
				*first_map, setup.session, first_map_request, current.first, current.marker + 6U);
			complete_map(*second_map,
						 *second_session,
						 second_map_request,
						 current.second,
						 current.marker + 7U);
			const auto converged =
				sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
			const auto composite_index = static_cast<std::size_t>(
				detail::sqlite_shm_reader_custody_kind::close_cut_or_composite);
			const auto waiter_index = static_cast<std::size_t>(
				detail::sqlite_shm_reader_custody_kind::bounded_waiter_or_continuation);
			const auto reporter_index =
				static_cast<std::size_t>(detail::sqlite_shm_reader_custody_kind::terminal_reporter);
			require(converged.outstanding_terminal_permit_count == 4U &&
						converged.live_custody_kind_counts[composite_index] == 1U &&
						converged.live_custody_kind_counts[waiter_index] == 1U &&
						converged.live_custody_kind_counts[reporter_index] == 1U &&
						converged.attachment_groups.size() == 1U &&
						converged.open_epochs.size() == 1U,
					"two terminal outcomes retain one composite, waiter, and reporter custody");

			const auto first_terminal =
				sqlite_same_process_shm_lease_test_peer::reader_session_terminal(
					setup.session_request,
					sqlite_shm_reader_session_terminal_kind::success,
					identity("test.registry.reader-live-close-pair-first-session", current.marker));
			const auto second_terminal =
				sqlite_same_process_shm_lease_test_peer::reader_session_terminal(
					second_session_request,
					sqlite_shm_reader_session_terminal_kind::success,
					identity("test.registry.reader-live-close-pair-second-session",
							 current.marker));
			require(setup.fixture.registry
							->complete_reader_session(
								*setup.fixture.family_pin, setup.session, first_terminal)
							.has_value() &&
						setup.fixture.registry
							->complete_reader_session(
								*setup.fixture.family_pin, *second_session, second_terminal)
							.has_value(),
					"drain both sessions behind the one live-close cut");
			auto ready = setup.fixture.registry->poll_reader_live_close_unmap_cut(
				*setup.fixture.family_pin, setup.open, *close, close_callback);
			require(ready &&
						ready->progress ==
							sqlite_shm_reader_unmap_cut_progress::native_effect_ready &&
						close->native_effect_ready(),
					"both session terminals release one composite native-unmap owner");

			const auto unmap_receipt =
				sqlite_same_process_shm_lease_test_peer::reader_unmap_terminal(
					*close,
					unmap_callback,
					sqlite_shm_reader_unmap_evidence_kind::exact_native_result,
					sqlite_ok_status,
					0,
					0,
					identity("test.registry.reader-live-close-pair-unmap-effect", current.marker),
					identity("test.registry.reader-live-close-pair-latch", current.marker));
			auto unmapped = setup.fixture.registry->complete_reader_live_close_unmap(
				*setup.fixture.family_pin, setup.open, *close, unmap_receipt);
			require(unmapped && close->close_ready(),
					"the one composite unmap advances the exact close owner");
			const auto close_receipt =
				sqlite_same_process_shm_lease_test_peer::reader_close_terminal(
					*close,
					close_callback,
					sqlite_shm_reader_close_evidence_kind::exact_native_result,
					sqlite_ok_status,
					identity("test.registry.reader-live-close-pair-close-effect", current.marker));
			auto closed = setup.fixture.registry->complete_reader_live_close(
				*setup.fixture.family_pin, setup.open, *close, close_receipt);
			require(closed && closed->kind() == sqlite_shm_reader_close_terminal_kind::closed &&
						setup.fixture.registry->release_reader_open(setup.open).has_value(),
					"the one composite owner closes and releases its exact open");
			retire_writer(*setup.coordinator, setup.holder, current.marker + 8U);
			require(setup.coordinator->revoke_writer_eligibility(setup.eligibility).has_value(),
					"revoke the two-map composite writer eligibility");
			require(!setup.coordinator->snapshot().quarantined &&
						setup.coordinator->snapshot().reader_registry_bound_group_count == 0U,
					"two pre-cut map terminals reach exact non-quarantined group quiescence");
			auto compact =
				sqlite_same_process_shm_lease_test_peer::export_reader_lifecycle_tombstones(
					*setup.coordinator);
			auto closes =
				sqlite_same_process_shm_lease_test_peer::export_reader_open_epoch_close_tombstones(
					*setup.coordinator);
			const auto replay_identities_are_nonempty = [](const auto& replay)
			{
				const auto identity_is_nonempty = [](const sqlite_backend_opaque_identity& value)
				{
					return !value.profile.empty() && !value.bytes.empty();
				};
				return std::ranges::all_of(replay.callback_invocation_tokens,
										   identity_is_nonempty) &&
					std::ranges::all_of(replay.effect_receipts, identity_is_nonempty) &&
					std::ranges::all_of(replay.session_terminal_receipts, identity_is_nonempty);
			};
			require(
				compact && compact->size() == 1U && closes && closes->size() == 1U &&
					compact->front().attachment.family() == setup.fixture.family &&
					closes->front().binding.family == setup.fixture.family &&
					replay_identities_are_nonempty(compact->front().replay_identities) &&
					replay_identities_are_nonempty(closes->front().replay_identities),
				"multi-map composite exports exact-family tombstones with valid replay identities");
			clean_fixture(setup.fixture);
		}
	}

	void verify_live_close_replay_domain_collisions_quarantine_every_composite_owner()
	{
		enum class collision_kind : std::uint8_t
		{
			map_effect_with_unmap_invocation,
			session_terminal_with_close_invocation,
		};
		struct row
		{
			std::uint8_t marker;
			collision_kind kind;
		};

		for (const auto current :
			 std::array{row{121U, collision_kind::map_effect_with_unmap_invocation},
						row{131U, collision_kind::session_terminal_with_close_invocation}})
		{
			auto setup = make_reader_candidate_setup(current.marker);
			auto handoff = form_reader_group(setup, current.marker + 1U);
			const auto map_request =
				reader_attachment_map_request(setup.session_request, current.marker + 2U);
			auto map = setup.fixture.registry->begin_reader_map(
				*setup.fixture.family_pin, setup.session, map_request);
			require(map && map->valid(), "begin the pre-cut map for replay-domain collision");
			const auto unmap_callback = callback(current.marker + 3U);
			const auto close_callback = callback(current.marker + 4U);
			auto close = setup.fixture.registry->begin_reader_live_close(
				*setup.fixture.family_pin,
				setup.open,
				handoff,
				sqlite_shm_reader_unmap_request{unmap_callback, 0, 0},
				sqlite_shm_reader_close_request{close_callback});
			require(close && close->valid() && !close->native_effect_ready() && !handoff.valid(),
					"seal the collision fixture behind one live-close composite");
			const auto before =
				sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
			require(before.map_attempts.size() == 1U && before.session_reservations.size() == 1U,
					"collision fixture retains exact map and session owners");
			const auto map_token = before.map_attempts.front().map_token;
			const auto session_token = before.session_reservations.front().session_token;

			sqlite_shm_lease_rejection rejection{};
			if (current.kind == collision_kind::map_effect_with_unmap_invocation)
			{
				const auto receipt = sqlite_same_process_shm_lease_test_peer::reader_attachment_map(
					map_request,
					setup.holder.generation(),
					mapping(setup.writer_attempt.native_page.get()),
					unmap_callback.invocation_token);
				auto completed = setup.fixture.registry->commit_reader_map(
					*setup.fixture.family_pin, *map, receipt, setup.session);
				require(!completed,
						"map effect cannot reuse the planned unmap invocation identity");
				rejection = completed.error();
			}
			else
			{
				const auto terminal =
					sqlite_same_process_shm_lease_test_peer::reader_session_terminal(
						setup.session_request,
						sqlite_shm_reader_session_terminal_kind::failure,
						close_callback.invocation_token);
				auto completed = setup.fixture.registry->complete_reader_session(
					*setup.fixture.family_pin, setup.session, terminal);
				require(!completed,
						"session terminal cannot reuse the planned close invocation identity");
				rejection = completed.error();
			}

			const auto lease = setup.coordinator->snapshot();
			const auto registry = setup.fixture.registry->snapshot();
			const auto lifecycle =
				sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
			const auto map_quarantine =
				std::ranges::find(lifecycle.terminal_quarantines,
								  map_token,
								  &sqlite_shm_reader_terminal_quarantine_test_view::owner_token);
			const auto session_quarantine =
				std::ranges::find(lifecycle.terminal_quarantines,
								  session_token,
								  &sqlite_shm_reader_terminal_quarantine_test_view::owner_token);
			const auto composite_index = static_cast<std::size_t>(
				detail::sqlite_shm_reader_custody_kind::close_cut_or_composite);
			const auto waiter_index = static_cast<std::size_t>(
				detail::sqlite_shm_reader_custody_kind::bounded_waiter_or_continuation);
			const auto reporter_index =
				static_cast<std::size_t>(detail::sqlite_shm_reader_custody_kind::terminal_reporter);
			require((rejection.reason == sqlite_shm_lease_rejection_reason::lifecycle_ambiguous ||
					 rejection.reason == sqlite_shm_lease_rejection_reason::receipt_mismatch) &&
						rejection.action == sqlite_shm_lease_recovery_action::quarantine_no_retry &&
						!map->valid() && !setup.session.valid() && !close->valid() &&
						!setup.open.valid() && lease.quarantined &&
						registry.quarantined_family_count == 1U,
					"cross-domain collision quarantines map, session, group, open, and family");
			require(
				lifecycle.outstanding_terminal_permit_count == 0U &&
					lifecycle.map_attempts.empty() && lifecycle.attachment_groups.size() == 1U &&
					lifecycle.open_epochs.size() == 1U &&
					lifecycle.attachment_groups.front().phase ==
						detail::sqlite_shm_reader_attachment_group_phase::terminal_quarantined &&
					lifecycle.open_epochs.front().phase ==
						detail::sqlite_shm_reader_connection_close_phase::terminal_quarantined &&
					map_quarantine != lifecycle.terminal_quarantines.end() &&
					session_quarantine != lifecycle.terminal_quarantines.end(),
				"collision retains exact map/session/group/open quarantine tombstones");
			require(lifecycle.live_custody_kind_counts[composite_index] == 0U &&
						lifecycle.live_custody_kind_counts[waiter_index] == 0U &&
						lifecycle.live_custody_kind_counts[reporter_index] == 0U,
					"collision leaves no live composite, waiter, or terminal-reporter custody");
		}
	}

	void verify_live_close_same_thread_and_reentrant_waits_quarantine_after_cut()
	{
		struct row
		{
			std::uint8_t marker;
			bool reentrant;
		};
		for (const auto current : std::array{row{82U, false}, row{92U, true}})
		{
			auto setup = make_reader_candidate_setup(current.marker);
			auto handoff = form_reader_group(setup, current.marker + 1U);
			const auto map_request =
				reader_attachment_map_request(setup.session_request, current.marker + 2U);
			auto map = setup.fixture.registry->begin_reader_map(
				*setup.fixture.family_pin, setup.session, map_request);
			require(map && map->valid(), "begin active map before same-thread live-close cut");
			const sqlite_shm_callback_execution_receipt unmap_callback{
				map_request.callback.thread_identity,
				current.reentrant ? 1U : 0U,
				identity("test.registry.reader-live-close-cut-unmap", current.marker)};
			const sqlite_shm_callback_execution_receipt close_callback{
				current.reentrant
					? identity("test.registry.reader-live-close-close-thread", current.marker)
					: map_request.callback.thread_identity,
				0U,
				identity("test.registry.reader-live-close-cut-close", current.marker)};
			auto failed = setup.fixture.registry->begin_reader_live_close(
				*setup.fixture.family_pin,
				setup.open,
				handoff,
				sqlite_shm_reader_unmap_request{unmap_callback, 0, 0},
				sqlite_shm_reader_close_request{close_callback});
			const auto lease = setup.coordinator->snapshot();
			const auto registry = setup.fixture.registry->snapshot();
			const auto lifecycle =
				sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
			require(
				!failed &&
					failed.error().reason ==
						sqlite_shm_lease_rejection_reason::lifecycle_ambiguous &&
					!handoff.valid() && setup.session.valid() && lease.quarantined &&
					registry.quarantined_family_count == 1U,
				current.reentrant
					? "reentrant live close consumes its cut then quarantines without native work"
					: "same-thread live close consumes its cut then quarantines without native "
					  "work");
			require(lifecycle.attachment_groups.size() == 1U &&
						lifecycle.open_epochs.size() == 1U && lifecycle.map_attempts.size() == 1U,
					"same-thread close retains the exact quarantined group, open, and map rows");
			require(lifecycle.outstanding_terminal_permit_count == 2U,
					"same-thread close retains only map and session terminal permits");
			require(
				lifecycle.attachment_groups.front().phase ==
						detail::sqlite_shm_reader_attachment_group_phase::terminal_quarantined &&
					lifecycle.open_epochs.front().phase ==
						detail::sqlite_shm_reader_connection_close_phase::terminal_quarantined,
				"same-thread close quarantines group and open after the cut");
			require(lifecycle.open_epochs.front().close_cut_sequence != 0U &&
						lifecycle.open_epochs.front().close_cut_sequence >
							lifecycle.attachment_groups.front().origin_sequence &&
						lifecycle.attachment_groups.front().destination_sequence >
							lifecycle.open_epochs.front().close_cut_sequence &&
						lifecycle.open_epochs.front().destination_sequence >
							lifecycle.open_epochs.front().close_cut_sequence,
					"same-thread close records quarantine destinations after its shared cut");

			const auto map_receipt =
				sqlite_same_process_shm_lease_test_peer::reader_attachment_zero_effect(
					*map,
					sqlite_shm_reader_attachment_zero_effect_kind::exact_no_attachment_change,
					map_request,
					sqlite_busy_status,
					nullptr,
					0,
					identity("test.registry.reader-live-close-cut-map-effect", current.marker));
			auto rejected_terminal = setup.fixture.registry->complete_reader_zero_attachment_map(
				*setup.fixture.family_pin, *map, map_receipt, setup.session);
			require(!rejected_terminal &&
						rejected_terminal.error().reason ==
							sqlite_shm_lease_rejection_reason::lifecycle_ambiguous &&
						!map->valid() && !setup.session.valid(),
					"post-cut quarantine exposes no later map or session authority");
		}
	}

	void verify_live_close_requires_the_exact_reader_open_at_every_boundary()
	{
		constexpr std::uint8_t marker = 170U;
		auto setup = make_reader_candidate_setup(marker);
		auto handoff = form_reader_group(setup, marker + 1U);
		auto peer_request = reader_pre_sqlite_request(
			setup.fixture,
			identity("test.registry.reader-live-close-peer-connection", marker),
			identity("test.registry.reader-live-close-peer-main-native", marker),
			identity("test.registry.reader-live-close-peer-main-xopen", marker),
			identity("test.registry.reader-live-close-peer-open", marker),
			identity("test.registry.reader-live-close-peer-cohort", marker),
			marker);
		auto peer_open = acquire_reader_open(setup.fixture, peer_request);
		const auto unmap_callback = callback(marker + 2U);
		const auto close_callback = callback(marker + 3U);
		auto close = setup.fixture.registry->begin_reader_live_close(
			*setup.fixture.family_pin,
			setup.open,
			handoff,
			sqlite_shm_reader_unmap_request{unmap_callback, 0, 0},
			sqlite_shm_reader_close_request{close_callback});
		require(close && close->valid() && !close->native_effect_ready() && !handoff.valid(),
				"seal one waiting live close beside a distinct open in the same family");

		const auto before_wrong_poll =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
		const auto registry_before_wrong_poll = setup.fixture.registry->snapshot();
		auto wrong_poll = setup.fixture.registry->poll_reader_live_close_unmap_cut(
			*setup.fixture.family_pin, peer_open, *close, close_callback);
		const auto after_wrong_poll =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
		const auto registry_after_wrong_poll = setup.fixture.registry->snapshot();
		require(
			!wrong_poll &&
				wrong_poll.error().reason == sqlite_shm_lease_rejection_reason::receipt_mismatch &&
				close->valid() && peer_open.valid() &&
				after_wrong_poll.last_issued_sequence == before_wrong_poll.last_issued_sequence &&
				after_wrong_poll.last_committed_sequence ==
					before_wrong_poll.last_committed_sequence &&
				after_wrong_poll.outstanding_terminal_permit_slots ==
					before_wrong_poll.outstanding_terminal_permit_slots &&
				after_wrong_poll.live_custody_kind_counts ==
					before_wrong_poll.live_custody_kind_counts &&
				registry_after_wrong_poll.active_activity_pin_count ==
					registry_before_wrong_poll.active_activity_pin_count &&
				registry_after_wrong_poll.active_reader_open_count ==
					registry_before_wrong_poll.active_reader_open_count,
			"peer-open poll is rejected before sequence, custody, pin, or open mutation");
		auto wrong_fail = setup.fixture.registry->fail_reader_live_close_unmap_cut_wait(
			*setup.fixture.family_pin,
			peer_open,
			*close,
			close_callback,
			sqlite_shm_retirement_wait_failure::timeout);
		const auto after_wrong_fail =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
		const auto registry_after_wrong_fail = setup.fixture.registry->snapshot();
		require(
			!wrong_fail &&
				wrong_fail.error().reason == sqlite_shm_lease_rejection_reason::receipt_mismatch &&
				close->valid() && peer_open.valid() && !close->native_effect_ready() &&
				after_wrong_fail.last_issued_sequence == after_wrong_poll.last_issued_sequence &&
				after_wrong_fail.last_committed_sequence ==
					after_wrong_poll.last_committed_sequence &&
				after_wrong_fail.outstanding_terminal_permit_slots ==
					after_wrong_poll.outstanding_terminal_permit_slots &&
				after_wrong_fail.live_custody_kind_counts ==
					after_wrong_poll.live_custody_kind_counts &&
				registry_after_wrong_fail.active_activity_pin_count ==
					registry_after_wrong_poll.active_activity_pin_count &&
				registry_after_wrong_fail.active_reader_open_count ==
					registry_after_wrong_poll.active_reader_open_count &&
				!setup.coordinator->snapshot().quarantined,
			"peer-open wait failure is rejected before sequence, custody, pin, or open mutation");

		const auto terminal = sqlite_same_process_shm_lease_test_peer::reader_session_terminal(
			setup.session_request,
			sqlite_shm_reader_session_terminal_kind::success,
			identity("test.registry.reader-live-close-peer-session", marker));
		require(setup.fixture.registry
					->complete_reader_session(*setup.fixture.family_pin, setup.session, terminal)
					.has_value(),
				"drain the exact live-close session after peer-open rejection");
		auto ready = setup.fixture.registry->poll_reader_live_close_unmap_cut(
			*setup.fixture.family_pin, setup.open, *close, close_callback);
		require(ready &&
					ready->progress == sqlite_shm_reader_unmap_cut_progress::native_effect_ready &&
					close->native_effect_ready(),
				"exact open advances its preserved composite owner");
		const auto unmap_receipt = sqlite_same_process_shm_lease_test_peer::reader_unmap_terminal(
			*close,
			unmap_callback,
			sqlite_shm_reader_unmap_evidence_kind::exact_native_result,
			sqlite_ok_status,
			0,
			0,
			identity("test.registry.reader-live-close-peer-unmap-effect", marker),
			identity("test.registry.reader-live-close-peer-unmap-latch", marker));
		const auto before_wrong_complete =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
		const auto registry_before_wrong_complete = setup.fixture.registry->snapshot();
		auto wrong_complete = setup.fixture.registry->complete_reader_live_close_unmap(
			*setup.fixture.family_pin, peer_open, *close, unmap_receipt);
		const auto after_wrong_complete =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
		const auto registry_after_wrong_complete = setup.fixture.registry->snapshot();
		require(!wrong_complete &&
					wrong_complete.error().reason ==
						sqlite_shm_lease_rejection_reason::receipt_mismatch &&
					close->valid() && peer_open.valid() && close->native_effect_ready() &&
					after_wrong_complete.last_issued_sequence ==
						before_wrong_complete.last_issued_sequence &&
					after_wrong_complete.last_committed_sequence ==
						before_wrong_complete.last_committed_sequence &&
					after_wrong_complete.outstanding_terminal_permit_slots ==
						before_wrong_complete.outstanding_terminal_permit_slots &&
					after_wrong_complete.live_custody_kind_counts ==
						before_wrong_complete.live_custody_kind_counts &&
					registry_after_wrong_complete.active_activity_pin_count ==
						registry_before_wrong_complete.active_activity_pin_count &&
					registry_after_wrong_complete.active_reader_open_count ==
						registry_before_wrong_complete.active_reader_open_count &&
					!setup.coordinator->snapshot().quarantined,
				"peer-open completion is rejected before sequence, custody, pin, or open mutation");
		auto unmapped = setup.fixture.registry->complete_reader_live_close_unmap(
			*setup.fixture.family_pin, setup.open, *close, unmap_receipt);
		require(unmapped &&
					unmapped->kind() == sqlite_shm_reader_unmap_terminal_kind::retired_confirmed &&
					close->close_ready(),
				"exact open consumes the same still-unspent unmap receipt");
		const auto close_receipt = sqlite_same_process_shm_lease_test_peer::reader_close_terminal(
			*close,
			close_callback,
			sqlite_shm_reader_close_evidence_kind::exact_native_result,
			sqlite_ok_status,
			identity("test.registry.reader-live-close-peer-close-effect", marker));
		const auto before_wrong_close =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
		auto wrong_close = setup.fixture.registry->complete_reader_live_close(
			*setup.fixture.family_pin, peer_open, *close, close_receipt);
		const auto after_wrong_close =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
		require(
			!wrong_close &&
				wrong_close.error().reason == sqlite_shm_lease_rejection_reason::receipt_mismatch &&
				close->valid() && close->close_ready() && peer_open.valid() &&
				after_wrong_close.last_issued_sequence == before_wrong_close.last_issued_sequence &&
				after_wrong_close.last_committed_sequence ==
					before_wrong_close.last_committed_sequence &&
				after_wrong_close.outstanding_terminal_permit_slots ==
					before_wrong_close.outstanding_terminal_permit_slots &&
				after_wrong_close.live_custody_kind_counts ==
					before_wrong_close.live_custody_kind_counts &&
				!setup.coordinator->snapshot().quarantined,
			"peer-open close is rejected before consuming the close-ready owner");
		auto closed = setup.fixture.registry->complete_reader_live_close(
			*setup.fixture.family_pin, setup.open, *close, close_receipt);
		require(closed && closed->kind() == sqlite_shm_reader_close_terminal_kind::closed &&
					setup.fixture.registry->release_reader_open(setup.open).has_value(),
				"exact open completes and releases the preserved composite owner");
		close_and_release_reader_open(setup.fixture, peer_open, marker + 4U);
		retire_writer(*setup.coordinator, setup.holder, marker + 5U);
		require(setup.coordinator->revoke_writer_eligibility(setup.eligibility).has_value(),
				"revoke exact-open binding writer eligibility");
		clean_fixture(setup.fixture);
	}

	void verify_live_close_wait_failures_synchronize_registry_quarantine()
	{
		struct row
		{
			std::uint8_t marker;
			sqlite_shm_retirement_wait_failure failure;
		};
		for (const auto current :
			 std::array{row{102U, sqlite_shm_retirement_wait_failure::timeout},
						row{112U, sqlite_shm_retirement_wait_failure::unknown}})
		{
			auto setup = make_reader_candidate_setup(current.marker);
			auto handoff = form_reader_group(setup, current.marker + 1U);
			const auto unmap_callback = callback(current.marker + 2U);
			const auto close_callback = callback(current.marker + 3U);
			auto close = setup.fixture.registry->begin_reader_live_close(
				*setup.fixture.family_pin,
				setup.open,
				handoff,
				sqlite_shm_reader_unmap_request{unmap_callback, 0, 0},
				sqlite_shm_reader_close_request{close_callback});
			require(close && close->valid() && !close->native_effect_ready() && !handoff.valid(),
					"live close retains one bounded other-thread wait owner");
			const auto prefailed_unmap_receipt =
				sqlite_same_process_shm_lease_test_peer::reader_unmap_terminal(
					*close,
					unmap_callback,
					sqlite_shm_reader_unmap_evidence_kind::exact_native_result,
					sqlite_ok_status,
					0,
					0,
					identity("test.registry.reader-live-close-wait-prefailed-effect",
							 current.marker),
					identity("test.registry.reader-live-close-wait-prefailed-latch",
							 current.marker));
			const auto before = setup.fixture.registry->snapshot();
			auto failed = setup.fixture.registry->fail_reader_live_close_unmap_cut_wait(
				*setup.fixture.family_pin, setup.open, *close, close_callback, current.failure);
			const auto lease = setup.coordinator->snapshot();
			const auto registry = setup.fixture.registry->snapshot();
			const auto lifecycle =
				sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
			require(
				!failed &&
					failed.error().reason ==
						sqlite_shm_lease_rejection_reason::lifecycle_ambiguous &&
					!close->valid() && lease.quarantined &&
					registry.quarantined_family_count == 1U &&
					registry.active_activity_pin_count == before.active_activity_pin_count &&
					lifecycle.attachment_groups.size() == 1U &&
					lifecycle.open_epochs.size() == 1U &&
					lifecycle.attachment_groups.front().phase ==
						detail::sqlite_shm_reader_attachment_group_phase::terminal_quarantined &&
					lifecycle.open_epochs.front().phase ==
						detail::sqlite_shm_reader_connection_close_phase::terminal_quarantined,
				"live-close bounded wait failure quarantines group, open, and family once");
			auto receipt_replay = setup.fixture.registry->complete_reader_live_close_unmap(
				*setup.fixture.family_pin, setup.open, *close, prefailed_unmap_receipt);
			const auto after_receipt_replay =
				sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
			require(!receipt_replay &&
						receipt_replay.error().reason !=
							sqlite_shm_lease_rejection_reason::retiring &&
						receipt_replay.error().action ==
							sqlite_shm_lease_recovery_action::quarantine_no_retry &&
						!close->valid() && setup.coordinator->snapshot().quarantined &&
						after_receipt_replay.last_committed_sequence ==
							lifecycle.last_committed_sequence &&
						after_receipt_replay.outstanding_terminal_permit_slots ==
							lifecycle.outstanding_terminal_permit_slots,
					"prefailed unmap evidence cannot revive native authority after wait failure");
			auto replay = setup.fixture.registry->poll_reader_live_close_unmap_cut(
				*setup.fixture.family_pin, setup.open, *close, close_callback);
			require(!replay && !close->valid() &&
						(replay.error().reason ==
							 sqlite_shm_lease_rejection_reason::lifecycle_ambiguous ||
						 replay.error().reason == sqlite_shm_lease_rejection_reason::quarantined ||
						 replay.error().reason == sqlite_shm_lease_rejection_reason::stale_token),
					"wait failure exposes no poll retry or reconstructed native authority");

			const auto terminal = sqlite_same_process_shm_lease_test_peer::reader_session_terminal(
				setup.session_request,
				sqlite_shm_reader_session_terminal_kind::failure,
				identity("test.registry.reader-live-close-wait-session", current.marker));
			require(setup.fixture.registry
							->complete_reader_session(
								*setup.fixture.family_pin, setup.session, terminal)
							.has_value() &&
						!setup.session.valid(),
					"wait-failed live close preserves its established session drain");
		}
	}

	struct reader_unpublished_cleanup_attempt
	{
		reader_candidate_setup candidate;
		sqlite_shm_reader_attachment_map_request map_request;
		sqlite_shm_verified_reader_attachment_post_map_receipt map_receipt;
		sqlite_backend_opaque_identity session_no_pointer_terminal_receipt;
		sqlite_shm_reader_attachment_map_inflight inflight;
		std::uint8_t marker{};
	};

	[[nodiscard]] reader_unpublished_cleanup_attempt
	prepare_reader_unpublished_cleanup_attempt(const std::uint8_t marker)
	{
		auto candidate = make_reader_candidate_setup(marker);
		auto map_request = reader_attachment_map_request(candidate.session_request,
														 static_cast<std::uint8_t>(marker + 1U));
		auto inflight = candidate.fixture.registry->begin_reader_map(
			*candidate.fixture.family_pin, candidate.session, map_request);
		require(inflight && inflight->valid(), "begin unpublished first reader map");
		auto map_receipt = sqlite_same_process_shm_lease_test_peer::reader_attachment_map(
			map_request,
			candidate.holder.generation(),
			mapping(candidate.writer_attempt.native_page.get()),
			identity("test.registry.reader-unpublished-map-effect",
					 static_cast<std::uint8_t>(marker + 1U)));
		sqlite_same_process_shm_lease_test_peer::fail_next_reader_map_terminal_transition(
			*candidate.coordinator);
		auto selected = candidate.fixture.registry->commit_reader_map(
			*candidate.fixture.family_pin, *inflight, map_receipt, candidate.session);
		const auto lease = candidate.coordinator->snapshot();
		const auto registry = candidate.fixture.registry->snapshot();
		require(
			!selected &&
				selected.error().reason ==
					sqlite_shm_lease_rejection_reason::unpublished_cleanup_required &&
				selected.error().action ==
					sqlite_shm_lease_recovery_action::attempt_nonremoving_unmap_then_outer_ioerr &&
				inflight->valid() && candidate.session.valid() && !lease.quarantined &&
				lease.reader_inflight_count == 1U && lease.reader_session_reservation_count == 1U &&
				lease.reader_unpublished_cleanup_admitted_count == 0U &&
				lease.reader_logical_ack_awaiting_count == 0U &&
				lease.reader_registry_activity_authority_count == 2U &&
				registry.active_activity_pin_count == 3U && registry.quarantined_family_count == 0U,
			"mapped first-map failure did not select one recoverable unpublished cleanup");
		return {
			std::move(candidate),
			std::move(map_request),
			std::move(map_receipt),
			identity("test.registry.reader-unpublished-session-terminal",
					 static_cast<std::uint8_t>(marker + 2U)),
			std::move(*inflight),
			marker,
		};
	}

	[[nodiscard]] sqlite_shm_verified_reader_unpublished_cleanup_receipt
	reader_unpublished_cleanup_receipt(const reader_unpublished_cleanup_attempt& attempt,
									   sqlite_shm_reader_attachment_map_request request,
									   sqlite_shm_reader_session_request session_request)
	{
		return sqlite_same_process_shm_lease_test_peer::reader_unpublished_cleanup(
			attempt.inflight,
			sqlite_shm_reader_unpublished_cleanup_entry_kind::exact_mapped_validation_failure,
			std::move(request),
			std::move(session_request),
			attempt.map_receipt.generation(),
			sqlite_ok_status,
			attempt.map_receipt.mapping().native_mapping,
			0,
			attempt.map_receipt.observed_attachment(),
			attempt.map_receipt.zero_resize_effect_receipt(),
			attempt.session_no_pointer_terminal_receipt);
	}

	struct reader_unpublished_cleanup_setup
	{
		reader_candidate_setup candidate;
		sqlite_shm_reader_attachment_map_request map_request;
		sqlite_backend_opaque_identity mapped_effect_receipt;
		sqlite_backend_opaque_identity session_no_pointer_terminal_receipt;
		sqlite_backend_opaque_identity cleanup_native_effect_receipt;
		sqlite_backend_opaque_identity cleanup_latch_reset_receipt;
		sqlite_shm_reader_unpublished_cleanup_obligation cleanup;
		std::uint8_t marker{};
	};

	[[nodiscard]] reader_unpublished_cleanup_setup
	begin_reader_unpublished_cleanup_attempt(reader_unpublished_cleanup_attempt attempt)
	{
		auto receipt = reader_unpublished_cleanup_receipt(
			attempt, attempt.map_request, attempt.candidate.session_request);
		auto cleanup = attempt.candidate.fixture.registry->begin_reader_unpublished_cleanup(
			*attempt.candidate.fixture.family_pin,
			attempt.inflight,
			receipt,
			attempt.candidate.session);
		const auto lease = attempt.candidate.coordinator->snapshot();
		const auto registry = attempt.candidate.fixture.registry->snapshot();
		const auto lifecycle = sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(
			*attempt.candidate.coordinator);
		const auto reservation = std::ranges::find_if(
			lifecycle.attachment_reservations,
			[&attempt](const sqlite_shm_reader_attachment_reservation_test_view& candidate)
			{
				return candidate.attachment == attempt.candidate.session_request.attachment;
			});
		require(cleanup && cleanup->valid() && !attempt.inflight.valid() &&
					!attempt.candidate.session.valid() && !lease.quarantined &&
					lease.reader_inflight_count == 0U && lease.reader_cleanup_count == 1U &&
					lease.reader_session_reservation_count == 0U &&
					lease.reader_session_owner_count == 0U &&
					lease.reader_unpublished_cleanup_admitted_count == 1U &&
					lease.reader_unpublished_cleanup_confirmed_count == 0U &&
					lease.reader_logical_ack_awaiting_count == 0U &&
					lease.reader_registry_activity_authority_count == 1U &&
					registry.active_activity_pin_count == 2U &&
					registry.active_reader_open_count == 1U &&
					registry.quarantined_family_count == 0U &&
					reservation != lifecycle.attachment_reservations.end() &&
					reservation->phase ==
						detail::sqlite_shm_reader_attachment_reservation_phase::
							unpublished_cleanup_admitted &&
					reservation->unpublished_cleanup_kind ==
						sqlite_shm_reader_unpublished_cleanup_entry_kind::
							exact_mapped_validation_failure &&
					reservation->logical_ack_phase ==
						detail::sqlite_shm_reader_logical_ack_phase::not_applicable &&
					reservation->cleanup_session_origin_sequence <
						reservation->cleanup_session_terminal_sequence &&
					reservation->cleanup_session_terminal_sequence <
						reservation->cleanup_cut_sequence &&
					reservation->cleanup_terminal_sequence == 0U &&
					reservation->logical_ack_sequence == 0U,
				"unpublished cleanup admission did not atomically consume map/session and retain "
				"one cleanup owner");
		return {
			std::move(attempt.candidate),
			std::move(attempt.map_request),
			attempt.map_receipt.zero_resize_effect_receipt(),
			std::move(attempt.session_no_pointer_terminal_receipt),
			identity("test.registry.reader-unpublished-cleanup-native-effect",
					 static_cast<std::uint8_t>(attempt.marker + 3U)),
			identity("test.registry.reader-unpublished-cleanup-latch-reset",
					 static_cast<std::uint8_t>(attempt.marker + 4U)),
			std::move(*cleanup),
			attempt.marker,
		};
	}

	[[nodiscard]] reader_unpublished_cleanup_setup
	make_confirmed_reader_unpublished_cleanup(const std::uint8_t marker)
	{
		auto setup = begin_reader_unpublished_cleanup_attempt(
			prepare_reader_unpublished_cleanup_attempt(marker));
		const auto terminal =
			sqlite_same_process_shm_lease_test_peer::reader_unpublished_cleanup_terminal(
				setup.cleanup,
				setup.map_request.callback,
				sqlite_shm_reader_unpublished_cleanup_evidence_kind::exact_native_result,
				sqlite_ok_status,
				0,
				0,
				setup.cleanup_native_effect_receipt,
				setup.cleanup_latch_reset_receipt);
		auto completed = setup.candidate.fixture.registry->complete_reader_unpublished_cleanup(
			*setup.candidate.fixture.family_pin, setup.cleanup, terminal);
		const auto lease = setup.candidate.coordinator->snapshot();
		const auto registry = setup.candidate.fixture.registry->snapshot();
		const auto lifecycle = sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(
			*setup.candidate.coordinator);
		const auto reservation = std::ranges::find_if(
			lifecycle.attachment_reservations,
			[&setup](const sqlite_shm_reader_attachment_reservation_test_view& candidate)
			{
				return candidate.attachment == setup.candidate.session_request.attachment;
			});
		require(completed &&
					completed->kind() ==
						sqlite_shm_reader_unpublished_cleanup_terminal_kind::confirmed &&
					completed->evidence_kind() ==
						sqlite_shm_reader_unpublished_cleanup_evidence_kind::exact_native_result &&
					completed->native_status() == sqlite_ok_status &&
					completed->outward_status() == sqlite_ioerr_status &&
					completed->native_effect_receipt() == setup.cleanup_native_effect_receipt &&
					completed->latch_reset_receipt() == setup.cleanup_latch_reset_receipt &&
					!setup.cleanup.valid() && !lease.quarantined &&
					lease.reader_cleanup_count == 0U &&
					lease.reader_unpublished_cleanup_admitted_count == 0U &&
					lease.reader_unpublished_cleanup_confirmed_count == 1U &&
					lease.reader_logical_ack_awaiting_count == 1U &&
					lease.reader_registry_activity_authority_count == 1U &&
					registry.active_activity_pin_count == 2U &&
					registry.active_reader_open_count == 1U &&
					registry.quarantined_family_count == 0U &&
					reservation != lifecycle.attachment_reservations.end() &&
					reservation->phase ==
						detail::sqlite_shm_reader_attachment_reservation_phase::
							unpublished_cleanup_confirmed &&
					reservation->logical_ack_phase ==
						detail::sqlite_shm_reader_logical_ack_phase::awaiting_sqlite_ack &&
					reservation->cleanup_cut_sequence < reservation->cleanup_terminal_sequence &&
					reservation->destination_sequence == reservation->cleanup_terminal_sequence &&
					reservation->logical_ack_sequence == 0U,
				"confirmed unpublished cleanup did not install one retained logical ack");
		return setup;
	}

	void close_and_retire_confirmed_unpublished_cleanup(reader_unpublished_cleanup_setup& setup,
														const std::uint8_t marker)
	{
		close_and_release_reader_open(setup.candidate.fixture,
									  setup.candidate.open,
									  marker,
									  sqlite_shm_reader_close_route::close_after_confirmed_unmap);
		retire_writer(*setup.candidate.coordinator,
					  setup.candidate.holder,
					  static_cast<std::uint8_t>(marker + 1U));
		require(setup.candidate.coordinator->revoke_writer_eligibility(setup.candidate.eligibility)
					.has_value(),
				"revoke confirmed unpublished-cleanup writer eligibility");
	}

	void verify_unpublished_cleanup_ack_blocks_fresh_admission_and_is_one_shot()
	{
		constexpr std::uint8_t marker = 92U;
		auto setup = make_confirmed_reader_unpublished_cleanup(marker);
		auto fresh_request = setup.candidate.pre_sqlite;
		fresh_request.read_transaction_epoch =
			identity("test.registry.reader-unpublished-fresh-transaction", marker);
		fresh_request.decode_attempt =
			identity("test.registry.reader-unpublished-fresh-decode", marker);
		fresh_request.authority_read_receipt =
			identity("test.registry.reader-unpublished-fresh-authority", marker);
		const auto sequence_before =
			sqlite_same_process_shm_registry_test_peer::reader_lifecycle_last_issued_sequence(
				*setup.candidate.fixture.registry);
		const auto registry_before = setup.candidate.fixture.registry->snapshot();
		const auto lease_before = setup.candidate.coordinator->snapshot();

		auto blocked_session = setup.candidate.fixture.registry->admit_reader_session_before_sqlite(
			*setup.candidate.fixture.family_pin, setup.candidate.open, fresh_request);
		auto blocked_map = setup.candidate.fixture.registry->begin_reader_map(
			*setup.candidate.fixture.family_pin, setup.candidate.session, setup.map_request);
		auto blocked_activity =
			setup.candidate.fixture.registry->acquire_activity(*setup.candidate.fixture.family_pin);

		auto second_owner_count = std::make_shared<std::atomic_int>(0);
		auto second_runtime_owner = std::make_shared<runtime_owner_probe>(second_owner_count);
		auto second_alias = register_alias(*setup.candidate.fixture.registry,
										   setup.candidate.fixture.process_instance,
										   setup.candidate.fixture.cohort,
										   static_cast<std::uint8_t>(marker + 20U),
										   second_runtime_owner);
		auto blocked_successor = setup.candidate.fixture.registry->install_or_join_family(
			*second_alias.alias, setup.candidate.fixture.family);
		const auto registry_blocked = setup.candidate.fixture.registry->snapshot();
		const auto lease_blocked = setup.candidate.coordinator->snapshot();
		require(
			blocked_session &&
				blocked_session->kind() ==
					sqlite_shm_reader_session_admission_kind::rejected_before_sqlite &&
				!blocked_session->has_proposal_custody() && blocked_session->rejection() &&
				blocked_session->rejection()->reason ==
					sqlite_shm_lease_rejection_reason::retiring &&
				blocked_session->rejection()->action ==
					sqlite_shm_lease_recovery_action::await_complete_attachment_gate_boundary &&
				!blocked_map &&
				blocked_map.error().reason == sqlite_shm_lease_rejection_reason::retiring &&
				blocked_map.error().action ==
					sqlite_shm_lease_recovery_action::await_complete_attachment_gate_boundary &&
				!blocked_activity &&
				blocked_activity.error().reason == sqlite_shm_lease_rejection_reason::retiring &&
				!blocked_successor &&
				blocked_successor.error().reason == sqlite_shm_lease_rejection_reason::retiring &&
				blocked_successor.error().action ==
					sqlite_shm_lease_recovery_action::await_complete_attachment_gate_boundary &&
				sqlite_same_process_shm_registry_test_peer::reader_lifecycle_last_issued_sequence(
					*setup.candidate.fixture.registry) == sequence_before &&
				registry_blocked.active_activity_pin_count ==
					registry_before.active_activity_pin_count &&
				registry_blocked.active_reader_open_count ==
					registry_before.active_reader_open_count &&
				lease_blocked.reader_unpublished_cleanup_confirmed_count ==
					lease_before.reader_unpublished_cleanup_confirmed_count &&
				lease_blocked.reader_logical_ack_awaiting_count == 1U &&
				lease_blocked.reader_session_reservation_count == 0U &&
				lease_blocked.reader_inflight_count == 0U && !lease_blocked.quarantined,
			"awaiting logical ack admitted a session, map, fresh epoch, activity, or successor");

		const auto ack_request = sqlite_shm_reader_logical_ack_request{
			callback(static_cast<std::uint8_t>(marker + 5U)), 0, 0};
		auto acknowledged = setup.candidate.fixture.registry->consume_reader_logical_ack(
			*setup.candidate.fixture.family_pin, setup.candidate.open, ack_request);
		const auto lease_acknowledged = setup.candidate.coordinator->snapshot();
		const auto registry_acknowledged = setup.candidate.fixture.registry->snapshot();
		const auto lifecycle = sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(
			*setup.candidate.coordinator);
		const auto reservation = std::ranges::find_if(
			lifecycle.attachment_reservations,
			[&setup](const sqlite_shm_reader_attachment_reservation_test_view& candidate)
			{
				return candidate.attachment == setup.candidate.session_request.attachment;
			});
		require(acknowledged &&
					acknowledged->phase() ==
						detail::sqlite_shm_reader_logical_ack_phase::consumed_by_exact_unmap &&
					acknowledged->outward_status() == sqlite_ok_status &&
					!acknowledged->delegated_native_effect() &&
					lease_acknowledged.reader_unpublished_cleanup_confirmed_count == 1U &&
					lease_acknowledged.reader_logical_ack_awaiting_count == 0U &&
					lease_acknowledged.reader_registry_activity_authority_count == 0U &&
					registry_acknowledged.active_activity_pin_count == 1U &&
					registry_acknowledged.active_reader_open_count == 1U &&
					reservation != lifecycle.attachment_reservations.end() &&
					reservation->logical_ack_phase ==
						detail::sqlite_shm_reader_logical_ack_phase::consumed_by_exact_unmap &&
					reservation->logical_ack_sequence > reservation->cleanup_terminal_sequence &&
					!lease_acknowledged.quarantined,
				"exact SQLite logical ack delegated native work or failed to release its owner");

		auto replay = setup.candidate.fixture.registry->consume_reader_logical_ack(
			*setup.candidate.fixture.family_pin, setup.candidate.open, ack_request);
		require(
			!replay && replay.error().reason == sqlite_shm_lease_rejection_reason::stale_token &&
				replay.error().action == sqlite_shm_lease_recovery_action::outer_ioerr_no_retry &&
				setup.candidate.coordinator->snapshot().reader_logical_ack_awaiting_count == 0U &&
				setup.candidate.fixture.registry->snapshot().active_activity_pin_count == 1U,
			"logical ack replay delegated a second native effect or corrupted the winner");

		auto admitted = setup.candidate.fixture.registry->admit_reader_session_before_sqlite(
			*setup.candidate.fixture.family_pin, setup.candidate.open, fresh_request);
		require(admitted &&
					admitted->kind() ==
						sqlite_shm_reader_session_admission_kind::
							reserved_for_local_proposal_candidate &&
					admitted->proposal_request() &&
					admitted->proposal_request()->attachment !=
						setup.candidate.session_request.attachment,
				"consumed ack did not reopen fresh nonreusable attachment admission");
		auto fresh_session = admitted->take_session();
		require(fresh_session && fresh_session->valid(), "take post-ack fresh session");
		const auto cancelled = sqlite_same_process_shm_lease_test_peer::reader_session_terminal(
			*admitted->proposal_request(),
			sqlite_shm_reader_session_terminal_kind::cancelled_before_authority_read,
			identity("test.registry.reader-unpublished-fresh-cancel", marker));
		require(setup.candidate.fixture.registry
					->complete_reader_session(
						*setup.candidate.fixture.family_pin, *fresh_session, cancelled)
					.has_value(),
				"cancel post-ack fresh session before native map");

		auto joined = setup.candidate.fixture.registry->install_or_join_family(
			*second_alias.alias, setup.candidate.fixture.family);
		require(joined.has_value(), "consumed ack did not unblock an exact family successor");
		second_alias.family_pin.emplace(std::move(*joined));
		require(
			setup.candidate.fixture.registry->release_family(*second_alias.family_pin).has_value(),
			"release post-ack successor family pin");
		second_alias.family_pin.reset();
		close_and_retire_confirmed_unpublished_cleanup(setup,
													   static_cast<std::uint8_t>(marker + 6U));
		unregister_alias(*setup.candidate.fixture.registry,
						 setup.candidate.fixture.process_instance,
						 setup.candidate.fixture.cohort,
						 second_alias);
		second_runtime_owner.reset();
		require(second_owner_count->load(std::memory_order_relaxed) == 1,
				"release post-ack successor runtime owner once");

		clean_fixture(setup.candidate.fixture);
	}

	void verify_unpublished_cleanup_ack_race_has_one_zero_native_winner()
	{
		constexpr std::uint8_t marker = 116U;
		auto setup = make_confirmed_reader_unpublished_cleanup(marker);
		struct outcome
		{
			bool succeeded{};
			bool delegated_native_effect{};
			int outward_status{sqlite_ioerr_status};
			sqlite_shm_lease_rejection_reason reason{
				sqlite_shm_lease_rejection_reason::invalid_request};
			sqlite_shm_lease_recovery_action action{
				sqlite_shm_lease_recovery_action::deny_before_native_map};
		};
		std::array<outcome, 2U> outcomes;
		std::barrier start{3};
		std::array<std::thread, 2U> contenders;
		const auto launch_contender = [&](outcome& exact_outcome, std::size_t index)
		{
			return std::thread{
				[&, index, exact_outcome = std::ref(exact_outcome)]
				{
					const auto request = sqlite_shm_reader_logical_ack_request{
						callback(static_cast<std::uint8_t>(marker + 5U + index)), 0, 0};
					start.arrive_and_wait();
					auto result = setup.candidate.fixture.registry->consume_reader_logical_ack(
						*setup.candidate.fixture.family_pin, setup.candidate.open, request);
					if (result)
					{
						exact_outcome.get().succeeded = true;
						exact_outcome.get().delegated_native_effect =
							result->delegated_native_effect();
						exact_outcome.get().outward_status = result->outward_status();
					}
					else
					{
						exact_outcome.get().reason = result.error().reason;
						exact_outcome.get().action = result.error().action;
					}
				}};
		};
		contenders[0U] = launch_contender(outcomes[0U], 0U);
		contenders[1U] = launch_contender(outcomes[1U], 1U);
		start.arrive_and_wait();
		for (auto& contender : contenders)
			contender.join();
		const auto winners = static_cast<std::size_t>(std::ranges::count_if(
			outcomes,
			[](const outcome& candidate)
			{
				return candidate.succeeded && !candidate.delegated_native_effect &&
					candidate.outward_status == sqlite_ok_status;
			}));
		const auto losers = static_cast<std::size_t>(std::ranges::count_if(
			outcomes,
			[](const outcome& candidate)
			{
				return !candidate.succeeded &&
					candidate.reason == sqlite_shm_lease_rejection_reason::stale_token &&
					candidate.action == sqlite_shm_lease_recovery_action::outer_ioerr_no_retry;
			}));
		const auto lease = setup.candidate.coordinator->snapshot();
		const auto registry = setup.candidate.fixture.registry->snapshot();
		require(winners == 1U && losers == 1U && lease.reader_logical_ack_awaiting_count == 0U &&
					lease.reader_unpublished_cleanup_confirmed_count == 1U &&
					lease.reader_registry_activity_authority_count == 0U &&
					registry.active_activity_pin_count == 1U &&
					registry.quarantined_family_count == 0U && !lease.quarantined,
				"logical-ack race did not produce one zero-native winner and one IOERR loser");
		close_and_retire_confirmed_unpublished_cleanup(setup,
													   static_cast<std::uint8_t>(marker + 8U));
		clean_fixture(setup.candidate.fixture);
	}

	void verify_close_consumes_unpublished_ack_and_recreates_exact_tombstone()
	{
		constexpr std::uint8_t marker = 140U;
		auto setup = make_confirmed_reader_unpublished_cleanup(marker);
		const auto lifecycle_before =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(
				*setup.candidate.coordinator);
		const auto ack_custody_index =
			static_cast<std::size_t>(detail::sqlite_shm_reader_custody_kind::logical_ack);
		const auto normal_unmap_index = static_cast<std::size_t>(
			detail::sqlite_shm_reader_custody_kind::normal_or_deferred_unmap);
		const auto close_callback = callback(static_cast<std::uint8_t>(marker + 5U));
		auto close = setup.candidate.fixture.registry->begin_reader_close(
			*setup.candidate.fixture.family_pin,
			setup.candidate.open,
			sqlite_shm_reader_close_request{close_callback});
		const auto lifecycle_admitted =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(
				*setup.candidate.coordinator);
		const auto reservation = std::ranges::find_if(
			lifecycle_admitted.attachment_reservations,
			[&setup](const sqlite_shm_reader_attachment_reservation_test_view& candidate)
			{
				return candidate.attachment == setup.candidate.session_request.attachment;
			});
		const auto open_epoch = std::ranges::find_if(
			lifecycle_admitted.open_epochs,
			[](const sqlite_shm_reader_open_epoch_test_view& candidate)
			{
				return candidate.phase ==
					detail::sqlite_shm_reader_connection_close_phase::close_admitted;
			});
		const auto lease_admitted = setup.candidate.coordinator->snapshot();
		const auto registry_admitted = setup.candidate.fixture.registry->snapshot();
		require(close && close->valid() &&
					close->route() == sqlite_shm_reader_close_route::close_after_confirmed_unmap &&
					lifecycle_before.live_custody_kind_counts[ack_custody_index] == 1U &&
					lifecycle_admitted.live_custody_kind_counts[ack_custody_index] == 0U &&
					lifecycle_admitted.live_custody_kind_counts[normal_unmap_index] ==
						lifecycle_before.live_custody_kind_counts[normal_unmap_index] &&
					reservation != lifecycle_admitted.attachment_reservations.end() &&
					reservation->logical_ack_phase ==
						detail::sqlite_shm_reader_logical_ack_phase::consumed_by_close &&
					open_epoch != lifecycle_admitted.open_epochs.end() &&
					reservation->logical_ack_sequence == open_epoch->close_cut_sequence &&
					lease_admitted.reader_logical_ack_awaiting_count == 0U &&
					lease_admitted.reader_registry_activity_authority_count == 0U &&
					registry_admitted.active_activity_pin_count == 1U &&
					registry_admitted.active_reader_open_count == 1U && !lease_admitted.quarantined,
				"close did not atomically consume pending ack before one xClose cut");

		const auto close_effect = identity("test.registry.reader-unpublished-close-effect", marker);
		const auto close_receipt = sqlite_same_process_shm_lease_test_peer::reader_close_terminal(
			*close,
			close_callback,
			sqlite_shm_reader_close_evidence_kind::exact_native_result,
			sqlite_ok_status,
			close_effect);
		auto completed = setup.candidate.fixture.registry->complete_reader_close(
			*setup.candidate.fixture.family_pin, setup.candidate.open, *close, close_receipt);
		require(completed && completed->kind() == sqlite_shm_reader_close_terminal_kind::closed &&
					completed->route() ==
						sqlite_shm_reader_close_route::close_after_confirmed_unmap &&
					completed->native_status() == sqlite_ok_status && !close->valid(),
				"close-after-confirmed-cleanup did not commit exactly one xClose terminal");
		auto close_replay = setup.candidate.fixture.registry->begin_reader_close(
			*setup.candidate.fixture.family_pin,
			setup.candidate.open,
			sqlite_shm_reader_close_request{close_callback});
		require(!close_replay &&
					close_replay.error().reason == sqlite_shm_lease_rejection_reason::stale_token &&
					setup.candidate.coordinator->snapshot().reader_logical_ack_awaiting_count == 0U,
				"closed ack route admitted a second unmap or close");
		require(
			setup.candidate.fixture.registry->release_reader_open(setup.candidate.open).has_value(),
			"release close-consumed reader open");

		retire_writer(*setup.candidate.coordinator,
					  setup.candidate.holder,
					  static_cast<std::uint8_t>(marker + 6U));
		require(setup.candidate.coordinator->revoke_writer_eligibility(setup.candidate.eligibility)
					.has_value(),
				"revoke close-consumed writer eligibility");
		auto local = sqlite_same_process_shm_lease_test_peer::export_reader_lifecycle_tombstones(
			*setup.candidate.coordinator);
		auto closes =
			sqlite_same_process_shm_lease_test_peer::export_reader_open_epoch_close_tombstones(
				*setup.candidate.coordinator);
		require(local && local->size() == 1U && closes && closes->size() == 1U &&
					local->front().phase ==
						detail::sqlite_shm_reader_attachment_reservation_phase::
							unpublished_cleanup_confirmed &&
					local->front().logical_ack_phase ==
						detail::sqlite_shm_reader_logical_ack_phase::consumed_by_close &&
					local->front().logical_ack_sequence == closes->front().close_cut_sequence &&
					local->front().replay_identities.callback_invocation_tokens ==
						std::vector{setup.map_request.callback.invocation_token} &&
					local->front().replay_identities.effect_receipts ==
						std::vector{setup.mapped_effect_receipt,
									setup.cleanup_native_effect_receipt,
									setup.cleanup_latch_reset_receipt} &&
					local->front().replay_identities.session_terminal_receipts ==
						std::vector{setup.session_no_pointer_terminal_receipt} &&
					!local->front().replay_identities.callback_free_terminal &&
					local->front().unpublished_cleanup_session_terminal_sequence -
							local->front().origin_sequence >
						2U &&
					local->front().unpublished_cleanup_cut_sequence ==
						local->front().unpublished_cleanup_session_terminal_sequence + 1U &&
					local->front().unpublished_cleanup_terminal_sequence ==
						local->front().destination_sequence &&
					local->front().logical_ack_sequence >
						local->front().unpublished_cleanup_terminal_sequence,
				"close-consumed compact tombstone lost exact cleanup/ack replay evidence");

		const auto attachment = setup.candidate.session_request.attachment;
		auto released =
			setup.candidate.fixture.registry->release_family(*setup.candidate.fixture.family_pin);
		require(released.has_value() && !setup.candidate.fixture.family_pin->valid() &&
					setup.candidate.fixture.registry->snapshot()
							.retired_reader_lifecycle_tombstone_count == 1U &&
					setup.candidate.fixture.registry->snapshot()
							.retired_reader_open_epoch_close_tombstone_count == 1U,
				"retire confirmed-cleanup family with both compact tombstones");
		setup.candidate.fixture.family_pin.reset();
		auto successor = setup.candidate.fixture.registry->install_or_join_family(
			*setup.candidate.fixture.alias, setup.candidate.fixture.family);
		require(successor.has_value(), "recreate confirmed-cleanup compact family");
		setup.candidate.fixture.family_pin.emplace(std::move(*successor));
		auto* successor_coordinator = sqlite_same_process_shm_registry_test_peer::coordinator(
			*setup.candidate.fixture.registry, setup.candidate.fixture.family);
		require(successor_coordinator != nullptr,
				"resolve recreated confirmed-cleanup coordinator");
		auto imported = sqlite_same_process_shm_lease_test_peer::export_reader_lifecycle_tombstones(
			*successor_coordinator);
		auto stale = sqlite_same_process_shm_lease_test_peer::check_reader_lifecycle_tombstone(
			*successor_coordinator, attachment);
		require(imported && *imported == *local && !stale &&
					stale.error().reason == sqlite_shm_lease_rejection_reason::stale_token,
				"family recreation changed compact cleanup evidence or revived the attachment");

		auto bad_sequence = *local;
		++bad_sequence.front().unpublished_cleanup_cut_sequence;
		auto rejected_sequence =
			sqlite_same_process_shm_lease_test_peer::import_reader_lifecycle_tombstones(
				*successor_coordinator, std::span{bad_sequence});
		auto bad_ack_sequence = *local;
		bad_ack_sequence.front().logical_ack_sequence =
			bad_ack_sequence.front().unpublished_cleanup_terminal_sequence;
		auto rejected_ack_sequence =
			sqlite_same_process_shm_lease_test_peer::import_reader_lifecycle_tombstones(
				*successor_coordinator, std::span{bad_ack_sequence});
		auto cross_domain_replay = *local;
		cross_domain_replay.front().replay_identities.session_terminal_receipts.front() =
			cross_domain_replay.front().replay_identities.effect_receipts.front();
		auto rejected_cross_domain =
			sqlite_same_process_shm_lease_test_peer::import_reader_lifecycle_tombstones(
				*successor_coordinator, std::span{cross_domain_replay});
		auto after_negative =
			sqlite_same_process_shm_lease_test_peer::export_reader_lifecycle_tombstones(
				*successor_coordinator);
		require(!rejected_sequence &&
					rejected_sequence.error().reason ==
						sqlite_shm_lease_rejection_reason::invalid_request &&
					!rejected_ack_sequence &&
					rejected_ack_sequence.error().reason ==
						sqlite_shm_lease_rejection_reason::invalid_request &&
					!rejected_cross_domain &&
					rejected_cross_domain.error().reason ==
						sqlite_shm_lease_rejection_reason::invalid_request &&
					after_negative && imported && *after_negative == *imported,
				"invalid compact sequence/domain replay changed the imported winner");
		clean_fixture(setup.candidate.fixture);
	}

	void verify_unpublished_cleanup_rejects_wrong_registry_binding_before_consumption()
	{
		constexpr std::uint8_t marker = 164U;
		auto attempt = prepare_reader_unpublished_cleanup_attempt(marker);
		auto wrong_request = attempt.map_request;
		wrong_request.alias_lifetime =
			identity("test.registry.reader-unpublished-wrong-alias", marker);
		const auto wrong_receipt = reader_unpublished_cleanup_receipt(
			attempt, std::move(wrong_request), attempt.candidate.session_request);
		const auto before = attempt.candidate.coordinator->snapshot();
		auto rejected = attempt.candidate.fixture.registry->begin_reader_unpublished_cleanup(
			*attempt.candidate.fixture.family_pin,
			attempt.inflight,
			wrong_receipt,
			attempt.candidate.session);
		const auto after = attempt.candidate.coordinator->snapshot();
		require(
			!rejected &&
				rejected.error().reason == sqlite_shm_lease_rejection_reason::receipt_mismatch &&
				attempt.inflight.valid() && attempt.candidate.session.valid() &&
				after.reader_inflight_count == before.reader_inflight_count &&
				after.reader_session_reservation_count == before.reader_session_reservation_count &&
				after.reader_unpublished_cleanup_admitted_count == 0U &&
				after.reader_registry_activity_authority_count ==
					before.reader_registry_activity_authority_count &&
				!after.quarantined,
			"wrong registry binding consumed or quarantined the exact cleanup owner");

		auto setup = begin_reader_unpublished_cleanup_attempt(std::move(attempt));
		const auto terminal =
			sqlite_same_process_shm_lease_test_peer::reader_unpublished_cleanup_terminal(
				setup.cleanup,
				setup.map_request.callback,
				sqlite_shm_reader_unpublished_cleanup_evidence_kind::exact_native_result,
				sqlite_ok_status,
				0,
				0,
				setup.cleanup_native_effect_receipt,
				setup.cleanup_latch_reset_receipt);
		require(setup.candidate.fixture.registry
					->complete_reader_unpublished_cleanup(
						*setup.candidate.fixture.family_pin, setup.cleanup, terminal)
					.has_value(),
				"correct cleanup receipt remains usable after binding rejection");
		const auto ack = sqlite_shm_reader_logical_ack_request{
			callback(static_cast<std::uint8_t>(marker + 5U)), 0, 0};
		require(setup.candidate.fixture.registry
					->consume_reader_logical_ack(
						*setup.candidate.fixture.family_pin, setup.candidate.open, ack)
					.has_value(),
				"consume cleanup ack after nonconsuming binding rejection");
		close_and_retire_confirmed_unpublished_cleanup(setup,
													   static_cast<std::uint8_t>(marker + 6U));
		clean_fixture(setup.candidate.fixture);
	}

	void verify_first_registry_reader_zero_attachment_route(
		const sqlite_shm_reader_attachment_zero_effect_kind kind,
		const int native_status,
		const int projected_status,
		const std::uint8_t marker)
	{
		auto setup = make_reader_candidate_setup(marker);
		const auto map_request = reader_attachment_map_request(
			setup.session_request, static_cast<std::uint8_t>(marker + 1U));
		const auto before_map = setup.coordinator->snapshot();
		require(setup.fixture.registry->snapshot().active_activity_pin_count == 2U &&
					before_map.reader_session_reservation_count == 1U &&
					before_map.reader_registry_activity_authority_count == 1U,
				"first zero-attachment fixture lacks writer/candidate baseline");
		auto inflight = setup.fixture.registry->begin_reader_map(
			*setup.fixture.family_pin, setup.session, map_request);
		require(inflight && inflight->valid() &&
					setup.fixture.registry->snapshot().active_activity_pin_count == 3U &&
					setup.coordinator->snapshot().reader_registry_activity_authority_count == 2U,
				"first zero-attachment map did not retain its candidate and predelegate pins");
		const auto receipt = sqlite_same_process_shm_lease_test_peer::reader_attachment_zero_effect(
			*inflight,
			kind,
			map_request,
			native_status,
			nullptr,
			0,
			identity("test.registry.reader-first-zero-effect",
					 static_cast<std::uint8_t>(marker + 1U)));
		auto completed = setup.fixture.registry->complete_reader_zero_attachment_map(
			*setup.fixture.family_pin, *inflight, receipt, setup.session);
		const auto lease = setup.coordinator->snapshot();
		const auto registry = setup.fixture.registry->snapshot();
		const auto lifecycle =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
		require(completed && completed->kind() == kind &&
					completed->native_status() == projected_status &&
					completed->native_mapping() == nullptr && !inflight->valid() &&
					!setup.session.valid() && lease.reader_inflight_count == 0U &&
					lease.reader_cleanup_count == 0U && lease.reader_attachment_group_count == 0U &&
					lease.reader_attachment_live_member_count == 0U &&
					lease.reader_attachment_audit_count == 0U &&
					lease.reader_session_reservation_count == 0U &&
					lease.reader_session_owner_count == 0U &&
					lease.reader_session_terminal_count == 0U &&
					lease.reader_attachment_zero_effect_terminal_count == 1U &&
					lease.reader_attachment_revoked_no_map_count == 1U &&
					lease.reader_registry_bound_group_count == 0U &&
					lease.reader_registry_bound_session_count == 0U &&
					lease.reader_registry_activity_authority_count == 0U && !lease.quarantined &&
					registry.active_activity_pin_count == 1U &&
					registry.active_reader_open_count == 1U &&
					registry.quarantined_family_count == 0U,
				"first zero-attachment terminal did not publish before releasing candidate and "
				"predelegate pins");

		auto replay = setup.fixture.registry->complete_reader_zero_attachment_map(
			*setup.fixture.family_pin, *inflight, receipt, setup.session);
		auto session_replay = setup.coordinator->begin_reader_session(setup.session_request);
		require(
			!replay && replay.error().reason == sqlite_shm_lease_rejection_reason::stale_token &&
				!session_replay &&
				session_replay.error().reason == sqlite_shm_lease_rejection_reason::stale_token &&
				setup.coordinator->snapshot().reader_attachment_zero_effect_terminal_count == 1U &&
				setup.fixture.registry->snapshot().active_activity_pin_count == 1U,
			"first zero-attachment tombstone admitted a receipt or attachment-epoch replay");

		close_and_release_reader_open(setup.fixture, setup.open, marker + 10U);
		retire_writer(*setup.coordinator, setup.holder, static_cast<std::uint8_t>(marker + 2U));
		require(setup.coordinator->revoke_writer_eligibility(setup.eligibility).has_value(),
				"revoke first zero-attachment writer eligibility");
		clean_fixture(setup.fixture);
	}

	enum class retired_compact_replay_role : std::uint8_t
	{
		none,
		first_map_callback,
		later_zero_callback,
		unmap_callback,
		first_map_effect,
		later_zero_effect,
		unmap_effect,
		latch_reset,
	};

	void verify_later_registry_reader_zero_attachment_route(
		const sqlite_shm_reader_attachment_zero_effect_kind kind,
		const int native_status,
		const int projected_status,
		const std::uint8_t marker,
		const retired_compact_replay_role replay_role = retired_compact_replay_role::none,
		const bool recreate_family = false)
	{
		auto fixture = make_fixture(marker, false);
		auto* coordinator = sqlite_same_process_shm_registry_test_peer::coordinator(
			*fixture.registry, fixture.family);
		require(coordinator != nullptr, "resolve later zero-attachment coordinator");
		auto pair = make_bound_pending_pair(fixture, marker);
		auto eligibility = install_eligibility(*coordinator,
											   fixture.family,
											   pair.first.request.connection_token,
											   pair.first.request.attachment.open_epoch(),
											   static_cast<std::uint8_t>(marker + 2U));
		std::array<sqlite_shm_pending_mapping*, 2U> pending{
			&pair.second_pending,
			&pair.first_pending,
		};
		auto gate = fixture.registry->advance_positive_writer_attachment_gate(
			*fixture.family_pin, pair.first.request.attachment, pending, eligibility);
		require(gate && gate->holders.size() == 2U,
				"publish later zero-attachment two-page writer generation");
		auto holders = std::move(gate->holders);
		const auto generation = holders.front().generation();

		auto pre_sqlite = reader_pre_sqlite_request(
			fixture,
			identity("test.registry.reader-later-zero-connection", marker),
			identity("test.registry.reader-later-zero-main-native", marker),
			identity("test.registry.reader-later-zero-main-xopen", marker),
			identity("test.registry.reader-later-zero-open", marker),
			identity("test.registry.reader-later-zero-cohort", marker),
			marker);
		auto open = acquire_reader_open(fixture, pre_sqlite);
		auto admitted = fixture.registry->admit_reader_session_before_sqlite(
			*fixture.family_pin, open, pre_sqlite);
		require(admitted && admitted->proposal_request(),
				"reserve later zero-attachment reader candidate");
		const auto session_request = *admitted->proposal_request();
		auto session = admitted->take_session();
		require(session && session->valid(), "take later zero-attachment reader session");
		const auto page_zero = reader_attachment_map_request(
			session_request, static_cast<std::uint8_t>(marker + 3U), 0);
		const auto first_map_effect = identity("test.registry.reader-later-zero-first-effect",
											   static_cast<std::uint8_t>(marker + 3U));
		auto first_map =
			fixture.registry->begin_reader_map(*fixture.family_pin, *session, page_zero);
		require(first_map && first_map->valid(), "begin later zero-attachment group-forming map");
		auto first_commit = fixture.registry->commit_reader_map(
			*fixture.family_pin,
			*first_map,
			sqlite_same_process_shm_lease_test_peer::reader_attachment_map(
				page_zero,
				generation,
				mapping(0, pair.first.native_page.get(), 8192U),
				first_map_effect),
			*session);
		require(first_commit && first_commit->formed_group(),
				"form later zero-attachment active group");
		auto handoff = first_commit->take_handoff();
		require(handoff && handoff->valid(), "take later zero-attachment group handoff");

		const auto baseline = coordinator->snapshot();
		const auto baseline_registry = fixture.registry->snapshot();
		require(baseline.reader_attachment_group_count == 1U &&
					baseline.reader_attachment_live_member_count == 1U &&
					baseline.reader_attachment_audit_count == 1U &&
					baseline.reader_session_owner_count == 1U &&
					baseline.reader_handoff_count == 1U &&
					baseline.reader_registry_bound_group_count == 1U &&
					baseline.reader_registry_bound_session_count == 1U &&
					baseline.reader_registry_activity_authority_count == 1U &&
					baseline.reader_attachment_zero_effect_terminal_count == 0U &&
					baseline_registry.active_activity_pin_count == 3U,
				"later zero-attachment fixture lacks exact active-group baseline");
		const auto page_one = reader_attachment_map_request(
			session_request, static_cast<std::uint8_t>(marker + 4U), 1);
		auto later_map =
			fixture.registry->begin_reader_map(*fixture.family_pin, *session, page_one);
		require(later_map && later_map->valid() &&
					fixture.registry->snapshot().active_activity_pin_count == 4U &&
					coordinator->snapshot().reader_registry_activity_authority_count == 2U,
				"unseen later page did not retain one separate predelegate");
		const auto later_zero_effect = identity("test.registry.reader-later-zero-effect",
												static_cast<std::uint8_t>(marker + 4U));
		const auto receipt = sqlite_same_process_shm_lease_test_peer::reader_attachment_zero_effect(
			*later_map, kind, page_one, native_status, nullptr, 0, later_zero_effect);
		auto completed = fixture.registry->complete_reader_zero_attachment_map(
			*fixture.family_pin, *later_map, receipt, *session);
		const auto after = coordinator->snapshot();
		const auto after_registry = fixture.registry->snapshot();
		require(completed && completed->kind() == kind &&
					completed->native_status() == projected_status &&
					completed->native_mapping() == nullptr && !later_map->valid() &&
					session->valid() && handoff->valid() &&
					after.reader_attachment_group_count == baseline.reader_attachment_group_count &&
					after.reader_attachment_live_member_count ==
						baseline.reader_attachment_live_member_count &&
					after.reader_attachment_audit_count == baseline.reader_attachment_audit_count &&
					after.reader_session_owner_count == baseline.reader_session_owner_count &&
					after.reader_handoff_count == baseline.reader_handoff_count &&
					after.reader_registry_bound_group_count ==
						baseline.reader_registry_bound_group_count &&
					after.reader_registry_bound_session_count ==
						baseline.reader_registry_bound_session_count &&
					after.reader_registry_activity_authority_count ==
						baseline.reader_registry_activity_authority_count &&
					after.reader_attachment_zero_effect_terminal_count == 1U &&
					after.reader_attachment_revoked_no_map_count == 0U && !after.quarantined &&
					after_registry.active_activity_pin_count ==
						baseline_registry.active_activity_pin_count &&
					after_registry.active_reader_open_count == 1U &&
					after_registry.quarantined_family_count == 0U,
				"later zero-attachment terminal changed group/session/handoff state or retained "
				"its predelegate");

		auto replay = fixture.registry->complete_reader_zero_attachment_map(
			*fixture.family_pin, *later_map, receipt, *session);
		require(!replay &&
					replay.error().reason == sqlite_shm_lease_rejection_reason::stale_token &&
					coordinator->snapshot().reader_attachment_zero_effect_terminal_count == 1U,
				"later zero-attachment attempt accepted a terminal receipt replay");

		const auto terminal = sqlite_same_process_shm_lease_test_peer::reader_session_terminal(
			session_request,
			sqlite_shm_reader_session_terminal_kind::success,
			identity("test.registry.reader-later-zero-terminal",
					 static_cast<std::uint8_t>(marker + 5U)));
		require(fixture.registry->complete_reader_session(*fixture.family_pin, *session, terminal)
					.has_value(),
				"close later zero-attachment active-group session");
		const auto unmap_callback = callback(static_cast<std::uint8_t>(marker + 6U));
		const auto unmap_effect = identity("test.registry.reader-later-zero-unmap-effect",
										   static_cast<std::uint8_t>(marker + 6U));
		const auto latch_reset = identity("test.registry.reader-later-zero-latch-reset",
										  static_cast<std::uint8_t>(marker + 6U));
		auto unmap =
			fixture.registry->begin_reader_unmap(*fixture.family_pin, *handoff, unmap_callback);
		require(unmap.has_value(), "admit later zero-attachment group unmap");
		const auto unmap_receipt = sqlite_same_process_shm_lease_test_peer::reader_unmap_terminal(
			*unmap,
			unmap_callback,
			sqlite_shm_reader_unmap_evidence_kind::exact_native_result,
			sqlite_ok_status,
			0,
			0,
			unmap_effect,
			latch_reset);
		require(fixture.registry->complete_reader_unmap(*fixture.family_pin, *unmap, unmap_receipt)
					.has_value(),
				"confirm later zero-attachment group unmap");
		close_and_release_reader_open(fixture,
									  open,
									  marker + 11U,
									  sqlite_shm_reader_close_route::close_after_confirmed_unmap);
		retire_writer(*coordinator, holders.front(), static_cast<std::uint8_t>(marker + 7U));
		require(coordinator->revoke_writer_eligibility(eligibility).has_value(),
				"revoke later zero-attachment writer eligibility");
		auto local = sqlite_same_process_shm_lease_test_peer::export_reader_lifecycle_tombstones(
			*coordinator);
		require(local && local->size() == 1U &&
					local->front().phase ==
						detail::sqlite_shm_reader_attachment_reservation_phase::retired_confirmed &&
					!local->front().replay_identities.callback_free_terminal &&
					local->front().replay_identities.callback_invocation_tokens ==
						std::vector{page_zero.callback.invocation_token,
									page_one.callback.invocation_token,
									unmap_callback.invocation_token} &&
					local->front().replay_identities.effect_receipts ==
						std::vector{first_map_effect, later_zero_effect, unmap_effect, latch_reset},
				"retired compact tombstone retains every map, zero-effect, unmap, and latch "
				"replay identity");
		if (replay_role == retired_compact_replay_role::none)
		{
			clean_fixture(fixture);
			return;
		}

		auto* active = coordinator;
		if (recreate_family)
		{
			auto released = fixture.registry->release_family(*fixture.family_pin);
			require(released.has_value() && !fixture.family_pin->valid(),
					"retire exact retired-compact replay source family");
			fixture.family_pin.reset();
			auto successor =
				fixture.registry->install_or_join_family(*fixture.alias, fixture.family);
			require(successor.has_value(), "recreate exact retired-compact replay family");
			fixture.family_pin.emplace(std::move(*successor));
			active = sqlite_same_process_shm_registry_test_peer::coordinator(*fixture.registry,
																			 fixture.family);
			require(active != nullptr, "resolve recreated retired-compact coordinator");
			auto imported =
				sqlite_same_process_shm_lease_test_peer::export_reader_lifecycle_tombstones(
					*active);
			require(imported && *imported == *local,
					"recreated retired compact payload is byte-for-byte exact");
		}

		const sqlite_backend_opaque_identity* replay_identity{};
		bool callback_identity{};
		switch (replay_role)
		{
			case retired_compact_replay_role::first_map_callback:
				replay_identity = &page_zero.callback.invocation_token;
				callback_identity = true;
				break;
			case retired_compact_replay_role::later_zero_callback:
				replay_identity = &page_one.callback.invocation_token;
				callback_identity = true;
				break;
			case retired_compact_replay_role::unmap_callback:
				replay_identity = &unmap_callback.invocation_token;
				callback_identity = true;
				break;
			case retired_compact_replay_role::first_map_effect:
				replay_identity = &first_map_effect;
				break;
			case retired_compact_replay_role::later_zero_effect:
				replay_identity = &later_zero_effect;
				break;
			case retired_compact_replay_role::unmap_effect:
				replay_identity = &unmap_effect;
				break;
			case retired_compact_replay_role::latch_reset:
				replay_identity = &latch_reset;
				break;
			case retired_compact_replay_role::none:
				break;
		}
		require(replay_identity != nullptr, "select one exact retired compact replay identity");
		require_compact_reader_identity_rejected_by_fresh_close(
			fixture,
			*active,
			*replay_identity,
			callback_identity,
			static_cast<std::uint8_t>(marker + 20U),
			recreate_family ? "imported retired compact identity cannot authorize a recreated close"
							: "local retired compact identity cannot authorize a later close");
	}

	void verify_retired_compact_all_replay_identities_are_rejected()
	{
		constexpr std::array replay_roles{
			retired_compact_replay_role::first_map_callback,
			retired_compact_replay_role::later_zero_callback,
			retired_compact_replay_role::unmap_callback,
			retired_compact_replay_role::first_map_effect,
			retired_compact_replay_role::later_zero_effect,
			retired_compact_replay_role::unmap_effect,
			retired_compact_replay_role::latch_reset,
		};
		for (const auto replay_role : replay_roles)
		{
			verify_later_registry_reader_zero_attachment_route(
				sqlite_shm_reader_attachment_zero_effect_kind::exact_no_attachment_change,
				sqlite_busy_status,
				sqlite_busy_status,
				80U,
				replay_role);
			verify_later_registry_reader_zero_attachment_route(
				sqlite_shm_reader_attachment_zero_effect_kind::exact_no_attachment_change,
				sqlite_busy_status,
				sqlite_busy_status,
				80U,
				replay_role,
				true);
		}
	}

	void verify_registry_reader_predecessor_transfer_retains_existing_route_lifetime()
	{
		struct row
		{
			sqlite_shm_reader_predecessor_map_kind kind;
			bool mapped;
		};
		const std::array rows{
			row{sqlite_shm_reader_predecessor_map_kind::exact_predecessor_no_attachment_route,
				false},
			row{sqlite_shm_reader_predecessor_map_kind::exact_predecessor_mapped_route, true},
		};

		for (std::size_t index = 0U; index < std::size(rows); ++index)
		{
			const auto marker = static_cast<std::uint8_t>(220U + index * 8U);
			auto setup = make_reader_candidate_setup(marker);
			const auto map_request = reader_attachment_map_request(
				setup.session_request, static_cast<std::uint8_t>(marker + 1U));
			auto inflight = setup.fixture.registry->begin_reader_map(
				*setup.fixture.family_pin, setup.session, map_request);
			require(inflight && inflight->valid() &&
						setup.fixture.registry->snapshot().active_activity_pin_count == 3U,
					"registry predecessor fixture retains candidate and predelegate activity");
			const auto& current = rows.at(index);
			const auto effect = identity("test.registry.reader-predecessor-native-effect",
										 static_cast<std::uint8_t>(marker + 2U));
			const auto receipt = sqlite_same_process_shm_lease_test_peer::reader_predecessor_map(
				*inflight,
				current.kind,
				map_request,
				sqlite_readonly_status,
				current.mapped ? setup.writer_attempt.native_page.get() : nullptr,
				0,
				effect);
			auto completed = setup.fixture.registry->complete_reader_predecessor_map(
				*setup.fixture.family_pin, *inflight, receipt, setup.session);
			const auto registry = setup.fixture.registry->snapshot();
			const auto lease = setup.coordinator->snapshot();
			const auto lifecycle =
				sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
			require(
				completed && completed->kind() == current.kind &&
					completed->native_status() ==
						(current.mapped ? sqlite_readonly_status
										: sqlite_readonly_cantinit_status) &&
					completed->native_mapping() ==
						(current.mapped ? setup.writer_attempt.native_page.get() : nullptr) &&
					!inflight->valid() && !setup.session.valid() &&
					registry.active_activity_pin_count == 2U &&
					registry.quarantined_family_count == 0U &&
					lease.reader_registry_activity_authority_count == 1U &&
					lease.reader_registry_bound_group_count == 0U &&
					lease.reader_registry_bound_session_count == 0U &&
					lease.reader_attachment_group_count == 0U &&
					lease.reader_predecessor_route_active_count == 1U &&
					lease.reader_predecessor_map_terminal_count == 1U &&
					lifecycle.predecessor_map_terminals.size() == 1U &&
					lifecycle.predecessor_map_terminals.front().native_effect_receipt == effect &&
					lifecycle.predecessor_map_terminals.front().observed_attachment_retained ==
						current.mapped &&
					!lease.quarantined,
				"registry predecessor terminal releases only the map predelegate while retaining "
				"one existing-route lifetime pin and zero proposal group/session authority");

			auto replay = setup.fixture.registry->complete_reader_predecessor_map(
				*setup.fixture.family_pin, *inflight, receipt, setup.session);
			auto remap = setup.fixture.registry->admit_reader_session_before_sqlite(
				*setup.fixture.family_pin, setup.open, setup.pre_sqlite);
			require(!replay &&
						replay.error().reason == sqlite_shm_lease_rejection_reason::stale_token &&
						remap &&
						remap->kind() ==
							sqlite_shm_reader_session_admission_kind::rejected_before_sqlite &&
						remap->rejection() &&
						remap->rejection()->reason == sqlite_shm_lease_rejection_reason::retiring &&
						setup.fixture.registry->snapshot().active_activity_pin_count == 2U &&
						!setup.coordinator->snapshot().quarantined,
					"predecessor active reservation rejects receipt replay and proposal remap");

			const auto unmap_effect = identity("test.registry.reader-predecessor-unmap-effect",
											   static_cast<std::uint8_t>(marker + 3U));
			const auto unmap_receipt =
				sqlite_same_process_shm_lease_test_peer::reader_predecessor_unmap(
					*completed,
					callback(static_cast<std::uint8_t>(marker + 4U)),
					sqlite_shm_reader_unmap_evidence_kind::exact_native_result,
					sqlite_ok_status,
					unmap_effect);
			auto mismatched_request = reader_pre_sqlite_request(
				setup.fixture,
				identity("test.registry.reader-predecessor-mismatched-connection",
						 static_cast<std::uint8_t>(marker + 20U)),
				identity("test.registry.reader-predecessor-mismatched-main-native",
						 static_cast<std::uint8_t>(marker + 20U)),
				identity("test.registry.reader-predecessor-mismatched-main-xopen",
						 static_cast<std::uint8_t>(marker + 20U)),
				identity("test.registry.reader-predecessor-mismatched-open",
						 static_cast<std::uint8_t>(marker + 20U)),
				identity("test.registry.reader-predecessor-mismatched-cohort",
						 static_cast<std::uint8_t>(marker + 20U)),
				static_cast<std::uint8_t>(marker + 20U));
			auto mismatched_open = acquire_reader_open(setup.fixture, mismatched_request);
			auto mismatched = setup.fixture.registry->complete_reader_predecessor_unmap(
				*setup.fixture.family_pin, mismatched_open, unmap_receipt);
			require(!mismatched &&
						mismatched.error().reason ==
							sqlite_shm_lease_rejection_reason::receipt_mismatch &&
						setup.fixture.registry->snapshot().active_activity_pin_count == 2U &&
						setup.coordinator->snapshot().reader_predecessor_route_active_count == 1U &&
						!setup.coordinator->snapshot().quarantined,
					"predecessor unmap receipt cannot cross reader open epochs or release custody");
			close_and_release_reader_open(
				setup.fixture, mismatched_open, static_cast<std::uint8_t>(marker + 21U));
			auto retired = setup.fixture.registry->complete_reader_predecessor_unmap(
				*setup.fixture.family_pin, setup.open, unmap_receipt);
			const auto retired_registry = setup.fixture.registry->snapshot();
			const auto retired_lease = setup.coordinator->snapshot();
			const auto retired_lifecycle =
				sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
			require(retired &&
						retired->kind() ==
							sqlite_shm_reader_unmap_terminal_kind::retired_confirmed &&
						retired->outward_status() == sqlite_ok_status &&
						retired->native_effect_receipt() == unmap_effect &&
						retired_registry.active_activity_pin_count == 1U &&
						retired_registry.quarantined_family_count == 0U &&
						retired_lease.reader_registry_activity_authority_count == 0U &&
						retired_lease.reader_predecessor_route_active_count == 0U &&
						retired_lease.reader_predecessor_route_retired_count == 1U &&
						retired_lifecycle.predecessor_map_terminals.size() == 1U &&
						retired_lifecycle.predecessor_map_terminals.front()
								.retirement_native_effect_receipt == unmap_effect &&
						!retired_lease.quarantined,
					"registry predecessor retirement releases the retained candidate lifetime only "
					"after exact existing-route unmap confirmation");
			auto unmap_replay = setup.fixture.registry->complete_reader_predecessor_unmap(
				*setup.fixture.family_pin, setup.open, unmap_receipt);
			require(!unmap_replay &&
						unmap_replay.error().reason ==
							sqlite_shm_lease_rejection_reason::stale_token &&
						setup.fixture.registry->snapshot().active_activity_pin_count == 1U &&
						!setup.coordinator->snapshot().quarantined,
					"registry predecessor unmap receipt is one-shot and does not release twice");
			close_and_release_reader_open(
				setup.fixture,
				setup.open,
				static_cast<std::uint8_t>(marker + 5U),
				sqlite_shm_reader_close_route::close_after_confirmed_unmap);
			retire_writer(*setup.coordinator, setup.holder, static_cast<std::uint8_t>(marker + 6U));
			require(setup.coordinator->revoke_writer_eligibility(setup.eligibility).has_value(),
					"revoke predecessor-unmapped writer eligibility");
			auto compact =
				sqlite_same_process_shm_lease_test_peer::export_reader_lifecycle_tombstones(
					*setup.coordinator);
			auto closes =
				sqlite_same_process_shm_lease_test_peer::export_reader_open_epoch_close_tombstones(
					*setup.coordinator);
			require(compact.has_value(),
					"predecessor-unmapped route passes lifecycle compact validation");
			require(closes.has_value(),
					"predecessor-unmapped route passes close tombstone validation");
			require(compact->size() == 1U,
					"predecessor-unmapped route exports one lifecycle tombstone");
			require(closes->size() == 2U,
					"predecessor-unmapped route and its cross-open probe export two close "
					"tombstones");
			require(compact->front().phase ==
							detail::sqlite_shm_reader_attachment_reservation_phase::
								predecessor_route_retired_confirmed &&
						compact->front().replay_identities.callback_invocation_tokens.size() ==
							2U &&
						compact->front().replay_identities.effect_receipts.size() == 2U,
					"predecessor-unmapped route exports exact map/unmap replay evidence after one "
					"later xClose");
			const auto before_release = setup.coordinator->snapshot();
			require(before_release.phase == sqlite_shm_mapping_generation_phase::empty &&
						!before_release.generation && before_release.mapping_page_count == 0U &&
						before_release.generation_authority_count == 0U &&
						before_release.eligibility_count == 0U &&
						before_release.writer_holder_count == 0U,
					"predecessor-unmapped fixture has no live writer ownership");
			require(before_release.reader_inflight_count == 0U &&
						before_release.reader_cleanup_count == 0U &&
						before_release.reader_handoff_count == 0U &&
						before_release.reader_attachment_group_count == 0U &&
						before_release.reader_session_reservation_count == 0U &&
						before_release.reader_registry_bound_group_count == 0U &&
						before_release.reader_registry_bound_session_count == 0U,
					"predecessor-unmapped fixture has no live reader descendants");
			require(before_release.reader_registry_open_count == 0U &&
						before_release.reader_open_close_owner_count == 0U &&
						before_release.reader_close_admitted_count == 0U &&
						before_release.reader_close_terminal_count == 0U &&
						before_release.reader_registry_activity_authority_count == 0U &&
						!before_release.reader_admission_visible && !before_release.quarantined,
					"predecessor-unmapped fixture has no live open or activity ownership");
			clean_fixture(setup.fixture);
			verify_predecessor_compact_family_recreation(
				setup.fixture, {static_cast<std::uint8_t>(52U + index), 2U, 2U});
		}
	}

	void verify_registry_reader_active_predecessor_is_retired_by_exact_xclose()
	{
		constexpr std::uint8_t marker = 40U;
		auto setup = make_reader_candidate_setup(marker);
		const auto map_request = reader_attachment_map_request(
			setup.session_request, static_cast<std::uint8_t>(marker + 1U));
		auto inflight = setup.fixture.registry->begin_reader_map(
			*setup.fixture.family_pin, setup.session, map_request);
		require(inflight && inflight->valid(), "begin active-predecessor close fixture");
		const auto map_effect = identity("test.registry.reader-predecessor-close-map-effect",
										 static_cast<std::uint8_t>(marker + 2U));
		const auto map_receipt = sqlite_same_process_shm_lease_test_peer::reader_predecessor_map(
			*inflight,
			sqlite_shm_reader_predecessor_map_kind::exact_predecessor_mapped_route,
			map_request,
			sqlite_readonly_status,
			setup.writer_attempt.native_page.get(),
			0,
			map_effect);
		auto predecessor = setup.fixture.registry->complete_reader_predecessor_map(
			*setup.fixture.family_pin, *inflight, map_receipt, setup.session);
		require(predecessor &&
					predecessor->kind() ==
						sqlite_shm_reader_predecessor_map_kind::exact_predecessor_mapped_route &&
					setup.fixture.registry->snapshot().active_activity_pin_count == 2U &&
					setup.coordinator->snapshot().reader_predecessor_route_active_count == 1U,
				"retain one exact predecessor-route activity until xClose");

		const auto before =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
		const auto close_callback = callback(static_cast<std::uint8_t>(marker + 3U));
		auto close = setup.fixture.registry->begin_reader_close(
			*setup.fixture.family_pin, setup.open, sqlite_shm_reader_close_request{close_callback});
		const auto admitted =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
		const auto runtime_pin_index = static_cast<std::size_t>(
			detail::sqlite_shm_reader_custody_kind::
				runtime_vfs_namespace_generation_native_mapping_lifetime_pin);
		require(close && close->valid() &&
					close->route() == sqlite_shm_reader_close_route::close_existing_predecessor &&
					before.live_custody_kind_counts[runtime_pin_index] == 1U &&
					admitted.live_custody_kind_counts[runtime_pin_index] == 1U &&
					setup.fixture.registry->snapshot().active_activity_pin_count == 2U &&
					setup.coordinator->snapshot().reader_predecessor_route_active_count == 1U,
				"active predecessor xClose cut retains its sole native-lifetime authority");

		const auto close_effect = identity("test.registry.reader-predecessor-close-effect",
										   static_cast<std::uint8_t>(marker + 4U));
		const auto close_receipt = sqlite_same_process_shm_lease_test_peer::reader_close_terminal(
			*close,
			close_callback,
			sqlite_shm_reader_close_evidence_kind::exact_native_result,
			sqlite_ok_status,
			close_effect);
		auto completed = setup.fixture.registry->complete_reader_close(
			*setup.fixture.family_pin, setup.open, *close, close_receipt);
		const auto retired_registry = setup.fixture.registry->snapshot();
		const auto retired_lease = setup.coordinator->snapshot();
		const auto retired_lifecycle =
			sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
		require(completed && completed->kind() == sqlite_shm_reader_close_terminal_kind::closed &&
					completed->route() ==
						sqlite_shm_reader_close_route::close_existing_predecessor &&
					completed->native_status() == sqlite_ok_status &&
					completed->native_effect_receipt() == close_effect && !close->valid() &&
					retired_registry.active_activity_pin_count == 1U &&
					retired_registry.quarantined_family_count == 0U &&
					retired_lease.reader_registry_activity_authority_count == 0U &&
					retired_lease.reader_predecessor_route_active_count == 0U &&
					retired_lease.reader_predecessor_route_retired_count == 1U &&
					retired_lifecycle.live_custody_kind_counts[runtime_pin_index] == 0U &&
					retired_lifecycle.predecessor_map_terminals.size() == 1U &&
					retired_lifecycle.predecessor_map_terminals.front()
							.predecessor_close_terminal_sequence != 0U &&
					!retired_lease.quarantined,
				"exact xClose atomically retires the predecessor route and releases its activity "
				"once");

		const auto late_unmap = sqlite_same_process_shm_lease_test_peer::reader_predecessor_unmap(
			*predecessor,
			callback(static_cast<std::uint8_t>(marker + 5U)),
			sqlite_shm_reader_unmap_evidence_kind::exact_native_result,
			sqlite_ok_status,
			identity("test.registry.reader-predecessor-close-late-unmap-effect",
					 static_cast<std::uint8_t>(marker + 6U)));
		auto rejected_unmap = setup.fixture.registry->complete_reader_predecessor_unmap(
			*setup.fixture.family_pin, setup.open, late_unmap);
		auto rejected_close = setup.fixture.registry->begin_reader_close(
			*setup.fixture.family_pin, setup.open, sqlite_shm_reader_close_request{close_callback});
		require(!rejected_unmap &&
					rejected_unmap.error().reason == sqlite_shm_lease_rejection_reason::stale_token,
				"xClose-retired predecessor rejects a later xShmUnmap as stale");
		require(!rejected_close &&
					rejected_close.error().reason ==
						sqlite_shm_lease_rejection_reason::stale_token &&
					setup.fixture.registry->snapshot().active_activity_pin_count == 1U,
				"xClose-retired predecessor rejects close replay without releasing twice");
		require(setup.fixture.registry->release_reader_open(setup.open).has_value() &&
					!setup.open.valid(),
				"release xClose-retired predecessor open");

		retire_writer(*setup.coordinator, setup.holder, static_cast<std::uint8_t>(marker + 7U));
		require(setup.coordinator->revoke_writer_eligibility(setup.eligibility).has_value(),
				"revoke xClose-retired predecessor writer eligibility");
		auto compact = sqlite_same_process_shm_lease_test_peer::export_reader_lifecycle_tombstones(
			*setup.coordinator);
		auto closes =
			sqlite_same_process_shm_lease_test_peer::export_reader_open_epoch_close_tombstones(
				*setup.coordinator);
		require(compact && compact->size() == 1U && closes && closes->size() == 1U &&
					compact->front().phase ==
						detail::sqlite_shm_reader_attachment_reservation_phase::
							predecessor_route_retired_confirmed &&
					compact->front().replay_identities.callback_invocation_tokens.size() == 1U &&
					compact->front().replay_identities.effect_receipts.size() == 1U,
				"xClose-retired predecessor exports map replay evidence and the separate close "
				"tombstone");
		clean_fixture(setup.fixture);
		verify_predecessor_compact_family_recreation(setup.fixture, {48U, 1U, 1U});
	}

	void verify_registry_reader_predecessor_xclose_failures_retain_activity()
	{
		enum class failure_kind : std::uint8_t
		{
			native_non_ok,
			unknown,
			mismatched_receipt,
			injected_commit,
		};
		struct row
		{
			failure_kind failure;
			std::uint8_t marker;
		};
		constexpr std::array rows{
			row{failure_kind::native_non_ok, 72U},
			row{failure_kind::unknown, 88U},
			row{failure_kind::mismatched_receipt, 104U},
			row{failure_kind::injected_commit, 120U},
		};

		for (const auto& current : rows)
		{
			auto setup = make_reader_candidate_setup(current.marker);
			const auto map_request = reader_attachment_map_request(
				setup.session_request, static_cast<std::uint8_t>(current.marker + 1U));
			auto inflight = setup.fixture.registry->begin_reader_map(
				*setup.fixture.family_pin, setup.session, map_request);
			require(inflight && inflight->valid(), "begin predecessor xClose failure fixture");
			const auto map_receipt =
				sqlite_same_process_shm_lease_test_peer::reader_predecessor_map(
					*inflight,
					sqlite_shm_reader_predecessor_map_kind::exact_predecessor_mapped_route,
					map_request,
					sqlite_readonly_status,
					setup.writer_attempt.native_page.get(),
					0,
					identity("test.registry.reader-predecessor-failed-close-map-effect",
							 static_cast<std::uint8_t>(current.marker + 2U)));
			auto predecessor = setup.fixture.registry->complete_reader_predecessor_map(
				*setup.fixture.family_pin, *inflight, map_receipt, setup.session);
			require(predecessor &&
						setup.fixture.registry->snapshot().active_activity_pin_count == 2U,
					"retain predecessor activity before failed xClose");

			const auto close_callback = callback(static_cast<std::uint8_t>(current.marker + 3U));
			auto close = setup.fixture.registry->begin_reader_close(
				*setup.fixture.family_pin,
				setup.open,
				sqlite_shm_reader_close_request{close_callback});
			require(close && close->valid() &&
						close->route() == sqlite_shm_reader_close_route::close_existing_predecessor,
					"admit one predecessor xClose failure terminal");
			if (current.failure == failure_kind::injected_commit)
				sqlite_same_process_shm_lease_test_peer::fail_next_reader_close_terminal_transition(
					*setup.coordinator);
			const auto exact_native = current.failure != failure_kind::unknown;
			const auto receipt_callback = current.failure == failure_kind::mismatched_receipt
				? callback(static_cast<std::uint8_t>(current.marker + 9U))
				: close_callback;
			const auto close_receipt =
				sqlite_same_process_shm_lease_test_peer::reader_close_terminal(
					*close,
					receipt_callback,
					exact_native ? sqlite_shm_reader_close_evidence_kind::exact_native_result
								 : sqlite_shm_reader_close_evidence_kind::throw_or_unknown,
					exact_native ? std::optional<int>{current.failure == failure_kind::native_non_ok
														  ? sqlite_busy_status
														  : sqlite_ok_status}
								 : std::nullopt,
					exact_native ? std::optional{identity(
									   "test.registry.reader-predecessor-failed-close-effect",
									   static_cast<std::uint8_t>(current.marker + 4U))}
								 : std::nullopt);
			auto completed = setup.fixture.registry->complete_reader_close(
				*setup.fixture.family_pin, setup.open, *close, close_receipt);
			const auto registry = setup.fixture.registry->snapshot();
			const auto lease = setup.coordinator->snapshot();
			const auto lifecycle =
				sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*setup.coordinator);
			const auto terminal_commit_rejected =
				current.failure == failure_kind::mismatched_receipt ||
				current.failure == failure_kind::injected_commit;
			const auto exact_failure_projection = terminal_commit_rejected ? !completed &&
					completed.error().reason ==
						sqlite_shm_lease_rejection_reason::lifecycle_ambiguous
																		   : completed &&
					completed->kind() ==
						sqlite_shm_reader_close_terminal_kind::terminal_quarantined;
			const auto exact_predecessor_terminal_projection =
				lifecycle.predecessor_map_terminals.size() == 1U &&
				(current.failure == failure_kind::mismatched_receipt
					 ? lifecycle.predecessor_map_terminals.front()
								 .predecessor_close_terminal_sequence == 0U &&
						 !lifecycle.terminal_quarantines.empty()
					 : lifecycle.predecessor_map_terminals.front()
							 .predecessor_close_terminal_sequence != 0U);
			require(exact_failure_projection && !close->valid() &&
						registry.active_activity_pin_count == 2U &&
						registry.quarantined_family_count == 1U &&
						lease.reader_registry_activity_authority_count == 1U &&
						lease.reader_predecessor_route_active_count == 0U &&
						lease.reader_predecessor_route_retired_count == 0U && lease.quarantined &&
						exact_predecessor_terminal_projection &&
						lifecycle.attachment_reservation_phase_counts[static_cast<std::size_t>(
							detail::sqlite_shm_reader_attachment_reservation_phase::
								terminal_quarantined)] == 1U,
					"non-OK, unknown, mismatched, and failed-commit predecessor xClose terminals "
					"quarantine without releasing retained native-lifetime activity");
		}
	}

	void verify_registry_reader_zero_attachment_success_routes()
	{
		verify_first_registry_reader_zero_attachment_route(
			sqlite_shm_reader_attachment_zero_effect_kind::exact_no_attachment_change,
			sqlite_busy_status,
			sqlite_busy_status,
			12U);
		verify_first_registry_reader_zero_attachment_route(
			sqlite_shm_reader_attachment_zero_effect_kind::exact_protocol_invalid_no_attachment,
			sqlite_ok_status,
			sqlite_ioerr_status,
			24U);
		verify_later_registry_reader_zero_attachment_route(
			sqlite_shm_reader_attachment_zero_effect_kind::exact_no_attachment_change,
			sqlite_busy_status,
			sqlite_busy_status,
			36U);
		verify_later_registry_reader_zero_attachment_route(
			sqlite_shm_reader_attachment_zero_effect_kind::exact_protocol_invalid_no_attachment,
			sqlite_ok_status,
			sqlite_ioerr_status,
			48U);
	}

	void verify_revoked_zero_effect_compact_replay_is_rejected()
	{
		for (std::size_t index = 0U; index < 4U; ++index)
		{
			constexpr std::uint8_t marker = 100U;
			const auto recreate = index >= 2U;
			const auto callback_identity = index % 2U == 0U;
			auto setup = make_reader_candidate_setup(marker);
			const auto map_request =
				reader_attachment_map_request(setup.session_request, marker + 1U);
			auto inflight = setup.fixture.registry->begin_reader_map(
				*setup.fixture.family_pin, setup.session, map_request);
			require(inflight && inflight->valid(), "begin revoked compact replay source map");
			const auto zero_effect =
				identity("test.registry.reader-revoked-compact-effect", marker);
			const auto receipt =
				sqlite_same_process_shm_lease_test_peer::reader_attachment_zero_effect(
					*inflight,
					sqlite_shm_reader_attachment_zero_effect_kind::exact_no_attachment_change,
					map_request,
					sqlite_busy_status,
					nullptr,
					0,
					zero_effect);
			require(setup.fixture.registry
						->complete_reader_zero_attachment_map(
							*setup.fixture.family_pin, *inflight, receipt, setup.session)
						.has_value(),
					"commit revoked compact replay source terminal");
			close_and_release_reader_open(setup.fixture, setup.open, marker + 10U);
			retire_writer(*setup.coordinator, setup.holder, marker + 2U);
			require(setup.coordinator->revoke_writer_eligibility(setup.eligibility).has_value(),
					"revoke revoked compact replay writer eligibility");

			auto local =
				sqlite_same_process_shm_lease_test_peer::export_reader_lifecycle_tombstones(
					*setup.coordinator);
			require(
				local && local->size() == 1U &&
					local->front().phase ==
						detail::sqlite_shm_reader_attachment_reservation_phase::revoked_no_map &&
					!local->front().replay_identities.callback_free_terminal &&
					local->front().replay_identities.callback_invocation_tokens ==
						std::vector{map_request.callback.invocation_token} &&
					local->front().replay_identities.effect_receipts == std::vector{zero_effect},
				"revoked compact tombstone retains its exact one/one replay payload");

			auto* active = setup.coordinator;
			if (recreate)
			{
				auto released = setup.fixture.registry->release_family(*setup.fixture.family_pin);
				require(released.has_value() && !setup.fixture.family_pin->valid(),
						"retire revoked compact replay source family");
				setup.fixture.family_pin.reset();
				auto successor = setup.fixture.registry->install_or_join_family(
					*setup.fixture.alias, setup.fixture.family);
				require(successor.has_value(), "recreate revoked compact replay target family");
				setup.fixture.family_pin.emplace(std::move(*successor));
				active = sqlite_same_process_shm_registry_test_peer::coordinator(
					*setup.fixture.registry, setup.fixture.family);
				require(active != nullptr, "resolve recreated revoked compact coordinator");
				auto imported =
					sqlite_same_process_shm_lease_test_peer::export_reader_lifecycle_tombstones(
						*active);
				require(imported && *imported == *local,
						"recreated revoked compact payload is byte-for-byte exact");
			}

			const auto& replay_identity = callback_identity
				? local->front().replay_identities.callback_invocation_tokens.front()
				: local->front().replay_identities.effect_receipts.front();
			require_compact_reader_identity_rejected_by_fresh_close(
				setup.fixture,
				*active,
				replay_identity,
				callback_identity,
				marker + 20U,
				recreate				? callback_identity
						? "imported revoked callback cannot authorize a recreated close"
						: "imported revoked effect cannot terminalize a recreated close"
					: callback_identity ? "local revoked callback cannot authorize a later close"
										: "local revoked effect cannot terminalize a later close");
		}
	}

	void verify_registry_reader_zero_attachment_invalid_proofs_are_all_or_none()
	{
		enum class invalid_proof_case : std::uint8_t
		{
			missing_effect,
			mismatched_request,
			predecessor_shape,
		};
		const auto run_invalid = [](const invalid_proof_case proof_case, const std::uint8_t marker)
		{
			auto setup = make_reader_candidate_setup(marker);
			const auto map_request = reader_attachment_map_request(
				setup.session_request, static_cast<std::uint8_t>(marker + 1U));
			auto inflight = setup.fixture.registry->begin_reader_map(
				*setup.fixture.family_pin, setup.session, map_request);
			require(inflight && inflight->valid() &&
						setup.fixture.registry->snapshot().active_activity_pin_count == 3U,
					"begin invalid zero-attachment proof fixture");
			auto receipt_request = map_request;
			if (proof_case == invalid_proof_case::mismatched_request)
				receipt_request.callback = callback(static_cast<std::uint8_t>(marker + 2U));
			const auto effect = proof_case == invalid_proof_case::missing_effect
				? sqlite_backend_opaque_identity{}
				: identity("test.registry.reader-invalid-zero-effect",
						   static_cast<std::uint8_t>(marker + 1U));
			const auto native_status = proof_case == invalid_proof_case::predecessor_shape
				? sqlite_readonly_status
				: sqlite_busy_status;
			const auto receipt =
				sqlite_same_process_shm_lease_test_peer::reader_attachment_zero_effect(
					*inflight,
					sqlite_shm_reader_attachment_zero_effect_kind::exact_no_attachment_change,
					std::move(receipt_request),
					native_status,
					nullptr,
					0,
					effect);
			auto completed = setup.fixture.registry->complete_reader_zero_attachment_map(
				*setup.fixture.family_pin, *inflight, receipt, setup.session);
			const auto lease = setup.coordinator->snapshot();
			const auto registry = setup.fixture.registry->snapshot();
			require(!completed &&
						completed.error().reason ==
							sqlite_shm_lease_rejection_reason::lifecycle_ambiguous &&
						!inflight->valid() && !setup.session.valid() && lease.quarantined &&
						lease.reader_attachment_group_count == 0U &&
						lease.reader_attachment_audit_count == 0U &&
						lease.reader_attachment_zero_effect_terminal_count == 0U &&
						lease.reader_attachment_revoked_no_map_count == 0U &&
						lease.reader_registry_activity_authority_count == 2U &&
						registry.active_activity_pin_count == 3U &&
						registry.active_reader_open_count == 1U &&
						registry.quarantined_family_count == 1U,
					"invalid zero-attachment proof published a terminal or released authority");
		};

		run_invalid(invalid_proof_case::missing_effect, 60U);
		run_invalid(invalid_proof_case::mismatched_request, 64U);
		run_invalid(invalid_proof_case::predecessor_shape, 68U);

		auto setup = make_reader_candidate_setup(72U);
		const auto map_request = reader_attachment_map_request(setup.session_request, 73U);
		auto inflight = setup.fixture.registry->begin_reader_map(
			*setup.fixture.family_pin, setup.session, map_request);
		require(inflight && inflight->valid(), "begin injected zero-attachment terminal fixture");
		const auto receipt = sqlite_same_process_shm_lease_test_peer::reader_attachment_zero_effect(
			*inflight,
			sqlite_shm_reader_attachment_zero_effect_kind::exact_no_attachment_change,
			map_request,
			sqlite_busy_status,
			nullptr,
			0,
			identity("test.registry.reader-injected-zero-effect", 73U));
		sqlite_same_process_shm_lease_test_peer::fail_next_reader_map_terminal_transition(
			*setup.coordinator);
		auto completed = setup.fixture.registry->complete_reader_zero_attachment_map(
			*setup.fixture.family_pin, *inflight, receipt, setup.session);
		const auto lease = setup.coordinator->snapshot();
		const auto registry = setup.fixture.registry->snapshot();
		require(!completed &&
					completed.error().reason ==
						sqlite_shm_lease_rejection_reason::lifecycle_ambiguous &&
					!inflight->valid() && !setup.session.valid() && lease.quarantined &&
					lease.reader_attachment_group_count == 0U &&
					lease.reader_attachment_audit_count == 0U &&
					lease.reader_attachment_zero_effect_terminal_count == 0U &&
					lease.reader_attachment_revoked_no_map_count == 0U &&
					lease.reader_registry_activity_authority_count == 2U &&
					registry.active_activity_pin_count == 3U &&
					registry.active_reader_open_count == 1U &&
					registry.quarantined_family_count == 1U,
				"injected zero-attachment terminal published half a tombstone or released pins");
	}

	[[nodiscard]] sqlite_shm_reader_session_request
	direct_reader_session_request(const reader_candidate_setup& setup, const std::uint8_t marker)
	{
		auto attachment = sqlite_same_process_shm_lease_test_peer::reader_attachment_reservation(
			setup.fixture.family,
			setup.fixture.runtime_pin_identity,
			setup.fixture.alias_lifetime,
			identity("test.registry.reader-open-direct-connection", marker),
			identity("test.registry.reader-open-direct-main-native", marker),
			identity("test.registry.reader-open-direct-main-xopen", marker),
			identity("test.registry.reader-open-direct-open", marker),
			setup.holder.generation(),
			identity("test.registry.reader-open-direct-cohort", marker),
			setup.fixture.registration_epoch,
			identity("test.registry.reader-open-direct-attachment", marker));
		require(attachment.has_value(), "bind open-lineage direct reader attachment");
		return {
			std::move(*attachment),
			reader_session_execution(marker),
			identity("test.registry.reader-open-direct-transaction", marker),
			identity("test.registry.reader-open-direct-decode", marker),
			identity("test.registry.reader-open-direct-authority", marker),
		};
	}

	[[nodiscard]] sqlite_shm_reader_map_request
	direct_reader_map_request(const reader_candidate_setup& setup, const std::uint8_t marker)
	{
		return {
			setup.fixture.family,
			setup.fixture.alias_lifetime,
			identity("test.registry.reader-open-raw-connection", marker),
			callback(marker),
			0,
			4096,
			0,
		};
	}

	void verify_reader_ordinary_route_has_zero_proposal_custody()
	{
		auto fixture = make_fixture(146U, false);
		auto* coordinator = sqlite_same_process_shm_registry_test_peer::coordinator(
			*fixture.registry, fixture.family);
		require(coordinator != nullptr, "resolve ordinary reader family coordinator");
		sqlite_same_process_shm_registry_test_peer::exhaust_counter(
			*fixture.registry,
			detail::sqlite_shm_registry_counter_for_testing::reader_attachment_epoch);
		const auto request = reader_pre_sqlite_request(
			fixture,
			identity("test.registry.reader-ordinary-connection", 146U),
			identity("test.registry.reader-ordinary-main-native", 146U),
			identity("test.registry.reader-ordinary-main-xopen", 146U),
			identity("test.registry.reader-ordinary-open", 146U),
			identity("test.registry.reader-ordinary-callback-cohort", 146U),
			146U);
		auto open = acquire_reader_open(fixture, request);
		const auto registry_before = fixture.registry->snapshot();
		const auto lease_before = coordinator->snapshot();
		auto admitted = fixture.registry->admit_reader_session_before_sqlite(
			*fixture.family_pin, open, request);
		require(admitted &&
					admitted->kind() ==
						sqlite_shm_reader_session_admission_kind::
							existing_or_ordinary_predecessor_zero_proposal_custody &&
					!admitted->has_proposal_custody() && !admitted->proposal_request() &&
					!admitted->rejection() && !admitted->take_session(),
				"ordinary reader route minted proposal identity, epoch, or session custody");
		const auto registry_after = fixture.registry->snapshot();
		const auto lease_after = coordinator->snapshot();
		require(
			registry_after.active_activity_pin_count == registry_before.active_activity_pin_count &&
				lease_after.reader_session_reservation_count ==
					lease_before.reader_session_reservation_count &&
				lease_after.reader_session_owner_count == lease_before.reader_session_owner_count &&
				lease_after.reader_attachment_group_count ==
					lease_before.reader_attachment_group_count &&
				lease_after.reader_registry_activity_authority_count == 0U &&
				!lease_after.quarantined,
			"ordinary reader route changed registry or lease proposal custody");
		close_and_release_reader_open(fixture, open, 149U);
		clean_fixture(fixture);
	}

	void verify_registry_reader_and_direct_routes_cannot_mix()
	{
		auto fixture = make_fixture(147U, false);
		auto* coordinator = sqlite_same_process_shm_registry_test_peer::coordinator(
			*fixture.registry, fixture.family);
		require(coordinator != nullptr, "resolve registry reader mixing coordinator");
		const auto writer = writer_request(fixture.family,
										   fixture.alias_lifetime,
										   identity("test.registry.reader-mixing-connection", 147U),
										   identity("test.registry.reader-mixing-open", 147U),
										   147U);
		auto eligibility = install_eligibility(*coordinator,
											   fixture.family,
											   writer.connection_token,
											   writer.attachment.open_epoch(),
											   148U);
		auto gate = fixture.registry->advance_positive_writer_attachment_gate(
			*fixture.family_pin,
			writer.attachment,
			std::span<sqlite_shm_pending_mapping*>{},
			eligibility);
		require(gate &&
					gate->progress ==
						sqlite_shm_positive_writer_attachment_gate_progress::complete &&
					gate->holders.empty(),
				"activate exact writer group for reader route-mixing test");
		auto attempt = begin_bound_route_attempt_for_request(
			fixture,
			writer,
			sqlite_writer_shm_mapping_semantic_route::one_one_preexisting_grown,
			147U);
		auto writer_receipt = validate_bound_route(
			attempt, sqlite_writer_shm_mapping_semantic_route::one_one_preexisting_grown, 147U);
		require(writer_receipt.has_value(), "validate reader route-mixing writer receipt");
		auto holder = fixture.registry->complete_gate_winning_writer_map_before_callback_return(
			*fixture.family_pin, attempt.post_native, *writer_receipt);
		require(holder && holder->valid(), "publish reader route-mixing writer generation");

		const auto pre_sqlite = reader_pre_sqlite_request(fixture, writer, 149U);
		auto open = acquire_reader_open(fixture, pre_sqlite);
		auto admitted = fixture.registry->admit_reader_session_before_sqlite(
			*fixture.family_pin, open, pre_sqlite);
		require(admitted &&
					admitted->kind() ==
						sqlite_shm_reader_session_admission_kind::
							reserved_for_local_proposal_candidate &&
					admitted->has_proposal_custody() && admitted->proposal_request() &&
					!admitted->rejection(),
				"reserve exact registry-bound reader candidate");
		const auto bound_request = *admitted->proposal_request();
		auto bound_session = admitted->take_session();
		require(bound_session && bound_session->valid(),
				"take exact registry-bound reader session owner");
		auto copied_identity_direct = coordinator->begin_reader_session(bound_request);
		require(!copied_identity_direct &&
					copied_identity_direct.error().reason ==
						sqlite_shm_lease_rejection_reason::receipt_mismatch,
				"copied registry identity recreated a direct reader session");
		const auto bound_map_request = reader_attachment_map_request(bound_request, 150U);
		auto bound_through_direct =
			coordinator->begin_reader_map(*bound_session, bound_map_request);
		require(!bound_through_direct &&
					bound_through_direct.error().reason ==
						sqlite_shm_lease_rejection_reason::receipt_mismatch &&
					bound_session->valid(),
				"registry-bound reader session entered the direct map route");
		const auto bound_terminal =
			sqlite_same_process_shm_lease_test_peer::reader_session_terminal(
				bound_request,
				sqlite_shm_reader_session_terminal_kind::cancelled_before_authority_read,
				identity("test.registry.reader-bound-cancelled", 150U));
		require(sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*coordinator)
						.outstanding_terminal_permit_count == 3U,
				"registry-bound session retains one terminal plus two open-close permits");
		auto bound_terminal_direct =
			coordinator->complete_reader_session(*bound_session, bound_terminal);
		require(!bound_terminal_direct &&
					bound_terminal_direct.error().reason ==
						sqlite_shm_lease_rejection_reason::receipt_mismatch &&
					bound_terminal_direct.error().action ==
						sqlite_shm_lease_recovery_action::resubmit_via_bound_route &&
					bound_session->valid() &&
					sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*coordinator)
							.outstanding_terminal_permit_count == 3U,
				"registry-bound session terminal bypassed its registry wrapper");
		std::atomic_bool wrapper_started{};
		std::atomic_bool wrapper_succeeded{};
		sqlite_same_process_shm_registry_test_peer::lock_state_mutex(*fixture.registry);
		std::thread terminal_wrapper{[&]
									 {
										 wrapper_started.store(true, std::memory_order_release);
										 auto result = fixture.registry->complete_reader_session(
											 *fixture.family_pin, *bound_session, bound_terminal);
										 wrapper_succeeded.store(result.has_value(),
																 std::memory_order_release);
									 }};
		while (!wrapper_started.load(std::memory_order_acquire))
			std::this_thread::yield();
		sqlite_same_process_shm_registry_test_peer::unlock_state_mutex(*fixture.registry);
		terminal_wrapper.join();
		require(wrapper_succeeded.load(std::memory_order_acquire) && !bound_session->valid() &&
					fixture.registry->snapshot().active_activity_pin_count == 1U &&
					sqlite_same_process_shm_lease_test_peer::reader_lifecycle_view(*coordinator)
							.outstanding_terminal_permit_count == 2U,
				"registry wrapper terminalized the bound session and released activity outside "
				"the registry lock");
		close_and_release_reader_open(fixture, open, 153U);

		auto direct_attachment =
			sqlite_same_process_shm_lease_test_peer::reader_attachment_reservation(
				fixture.family,
				fixture.runtime_pin_identity,
				fixture.alias_lifetime,
				writer.connection_token,
				writer.attachment.main_native_file_receipt(),
				writer.attachment.main_xopen_receipt(),
				writer.attachment.open_epoch(),
				holder->generation(),
				writer.attachment.callback_cohort(),
				fixture.registration_epoch,
				identity("test.registry.reader-direct-attachment-epoch", 151U));
		require(direct_attachment.has_value(), "bind test-only direct reader identity");
		const auto direct_request = sqlite_shm_reader_session_request{
			std::move(*direct_attachment),
			reader_session_execution(151U),
			identity("test.registry.reader-direct-transaction", 151U),
			identity("test.registry.reader-direct-decode", 151U),
			identity("test.registry.reader-direct-authority", 151U),
		};
		auto direct_session = coordinator->begin_reader_session(direct_request);
		require(direct_session && direct_session->valid(), "begin direct reader session");
		const auto direct_map_request = reader_attachment_map_request(direct_request, 151U);
		auto direct_through_registry = fixture.registry->begin_reader_map(
			*fixture.family_pin, *direct_session, direct_map_request);
		require(!direct_through_registry &&
					direct_through_registry.error().reason ==
						sqlite_shm_lease_rejection_reason::receipt_mismatch &&
					direct_session->valid(),
				"direct reader session entered the registry-bound map route");
		const auto direct_terminal =
			sqlite_same_process_shm_lease_test_peer::reader_session_terminal(
				direct_request,
				sqlite_shm_reader_session_terminal_kind::cancelled_before_authority_read,
				identity("test.registry.reader-direct-cancelled", 151U));
		require(coordinator->complete_reader_session(*direct_session, direct_terminal) &&
					!direct_session->valid(),
				"close direct no-pointer reader session");

		retire_writer(*coordinator, *holder, 152U);
		require(coordinator->revoke_writer_eligibility(eligibility).has_value(),
				"revoke reader route-mixing writer eligibility");
		clean_fixture(fixture);
	}

